import type { FullProtocol } from "./types";

export const dermatologyFullProtocols9: FullProtocol[] = [
  {
    id: "fp-derm5-reacao-droga-dress",
    title: "DRESS — Reação a Droga com Eosinofilia e Sintomas Sistêmicos",
    categoryId: "dermatology", category: "Dermatologia",
    tags: ["DRESS", "farmacodermia", "eosinofilia", "febre", "orgao", "reativacao viral"],
    sections: [
      { id: "intro", title: "Introdução", content: "DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms) é farmacodermia grave com mortalidade de 10–20%, caracterizada por reação tardia (2–8 semanas após início da droga) com exantema, febre, eosinofilia, linfadenopatia e acometimento sistêmico. O diagnóstico é frequentemente tardio porque a apresentação simula infecção viral. A suspensão imediata do agente causador e corticoide sistêmico são o tratamento padrão.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026 · RegiSCAR." },
      { id: "def", title: "Definição", content: "Reação adversa medicamentosa grave (SCAR — Severe Cutaneous Adverse Reaction) caracterizada por:\n\nCritérios de RegiSCAR (3+ pontos = provável DRESS):\n• Febre ≥ 38,5°C (0)\n• Linfadenopatia ≥ 2 sítios (+1)\n• Acometimento de órgão interno: 1 (+1), ≥ 2 (+2)\n• Exantema típico (+1 a +2)\n• Eosinofilia: 700–1499 (+1), ≥ 1500 (+2)\n• Linfócitos atípicos (+1)\n• Resolução em > 15 dias (+1)\n• Ao menos 3 exames excluindo outras causas (+1)\n\nFatores predisponentes:\n• Predisposição genética (HLA-específicos):\n  — HLA-B*5701 + abacavir\n  — HLA-B*1502 + carbamazepina (asiáticos)\n  — HLA-A*3101 + carbamazepina (europeus)\n• Reativação de HHV-6, HHV-7, EBV, CMV (mecanismo central — papel chave)\n• Hospedeiro lentamente metabolizador\n\nMortalidade: 10–20% (principalmente por hepatite fulminante)" },
      { id: "screening", title: "Rastreamento e Identificação", content: "SUSPEITAR em paciente com:\n• Exantema generalizado 2–8 semanas após início de droga (especialmente anticonvulsivantes, antibióticos, alopurinol)\n• Febre alta persistente\n• Edema facial proeminente (CARACTERÍSTICO)\n• Linfadenopatia generalizada\n• Linfócitos atípicos no esfregaço\n• Eosinofilia\n• Hepatite com transaminases elevadas em paciente em uso de droga\n\nPERGUNTAS-CHAVE:\n• 'Que medicamentos novos foram iniciados nos últimos 2 meses?'\n• Incluir suplementos, fitoterápicos, contrastes\n• Reativação de HSV/varicela recente?\n\nSINAIS DE GRAVIDADE:\n• Eosinofilia > 1500\n• Hepatite (ALT > 2× LSN)\n• IRA\n• Pneumonite\n• Miocardite\n• Hipotensão\n• Choque" },
      { id: "etiology", title: "Etiologia", content: "DROGAS MAIS ASSOCIADAS (acrônimo BARMSON):\n• Anticonvulsivantes aromáticos: carbamazepina, fenitoína, fenobarbital, lamotrigina (maior risco)\n• Alopurinol\n• Sulfonamidas: sulfametoxazol-trimetoprim, sulfassalazina, dapsona\n• Minociclina (e outras tetraciclinas)\n• Antirretrovirais: abacavir, nevirapina\n• Antibióticos: vancomicina, beta-lactâmicos (raros)\n• Antitireoidianos: PTU, metimazol\n• Antimaláricos\n• Mexiletina\n\nFISIOPATOLOGIA:\n• Reação tardia mediada por células T (tipo IVb)\n• Acúmulo de metabólitos tóxicos em lentos metabolizadores\n• Reativação de herpesvírus (HHV-6 em > 80% dos casos)\n• Resposta imune cruzada (vírus + droga)\n• Período de incubação 2–8 semanas — característica importante" },
      { id: "clinical", title: "Apresentação Clínica", content: "Cronologia típica:\n• 2–8 semanas após início da droga (mais longo que SSJ/NET — 1–3 semanas)\n• Início insidioso\n\nManifestações cutâneas:\n• Exantema maculopapular morbiliforme generalizado\n• Edema facial proeminente (CARACTERÍSTICO — quase patognomônico)\n• Pode evoluir para eritrodermia\n• Vesículas, pústulas\n• Descamação após semanas\n• Mucosa: relativamente preservada (diferente de SSJ/NET)\n\nManifestações sistêmicas:\n• Febre alta (38,5–40°C)\n• Linfadenopatia generalizada\n• Hepatite (50–60% — pode ser fulminante!)\n• Nefrite intersticial (10–30%)\n• Pneumonite (25%)\n• Miocardite (até 8% — pode ser tardia!)\n• Encefalite (raro)\n• Tireoidite (tardia — meses)\n\nSequelas tardias (autoimunes):\n• Tireoidite autoimune (semanas a meses depois)\n• Diabetes mellitus tipo 1\n• Lupus, doença granulomatosa\n• Vitiligo" },
      { id: "diagnosis", title: "Diagnóstico", content: "Diagnóstico CLÍNICO + critérios RegiSCAR\n\nLaboratorial OBRIGATÓRIO:\n• Hemograma completo (eosinofilia ≥ 700, linfócitos atípicos)\n• ALT, AST, GGT, FA, bilirrubinas (hepatite)\n• Função renal: creatinina, ureia\n• EAS (proteinúria, eosinofilúria)\n• Glicemia (atenção: tireoidite/diabetes pode surgir)\n• Eletrólitos\n• CK, troponina (miocardite)\n• TSH, T4L (basal e seguimento)\n\nSorologias virais:\n• Anti-HSV, anti-VZV\n• HHV-6 PCR (reativação — confirma DRESS)\n• EBV, CMV (PCR ou sorologia)\n• Hepatite B, C\n• HIV\n\nImagem:\n• Rx tórax (pneumonite)\n• ECG (miocardite)\n• Ecocardiograma (se sinais cardíacos)\n\nBiópsia de pele (apoio diagnóstico, não obrigatória):\n• Infiltrado linfocitário perivascular\n• Eosinófilos\n• Edema dérmico\n• Necrose de ceratinócitos raros\n• Não é diagnóstica isoladamente — clínica é mais importante" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "• SSJ/NET (mucosa muito acometida, descolamento epidérmico, mortalidade alta, < 4 semanas de droga)\n• Infecção viral aguda (mononucleose, sarampo, rubéola — sem eosinofilia tão alta, sem hepatite tão grave)\n• Linfoma cutâneo (curso crônico, sem febre aguda)\n• Sepsis com exantema (sem cronologia medicamentosa, hemoculturas)\n• Doença de Still adulto (febre, exantema, mas sem eosinofilia e sem droga)\n• Vasculite cutânea (palpável, mais focal)\n• Síndrome de hipersensibilidade não-DRESS\n• PEGA (pústulas, sem hepatite grave, < 1 semana)" },
      { id: "conduct", title: "Conduta", content: "1. SUSPENSÃO IMEDIATA DO AGENTE CAUSADOR (MEDIDA MAIS IMPORTANTE):\n• Identificar TODOS os medicamentos iniciados nos últimos 2 meses\n• Suspender TODOS os suspeitos\n• Documentar como alergia/intolerância em prontuário\n• Reação cruzada: evitar anticonvulsivantes aromáticos relacionados (carbamazepina↔fenitoína↔fenobarbital)\n\n2. INTERNAÇÃO HOSPITALAR (sempre):\n• Pacientes com acometimento sistêmico: UTI\n• Monitorização contínua\n• Acompanhamento por dermatologia + clínica + nefrologia/hepatologia conforme acometimento\n\n3. CUIDADOS DE SUPORTE:\n• Hidratação IV (perdas pela pele desnudada)\n• Controle hidroeletrolítico\n• Cuidados de pele:\n  — Curativos não aderentes (Vaselina, parafina)\n  — Banho com SF morno\n  — Evitar saliva nas erosões\n  — Vaselina nos lábios\n• Profilaxia TEP (enoxaparina 40mg SC/dia)\n• Profilaxia úlcera de stress (omeprazol)\n• Nutrição (perdas calóricas — manter ingesta)\n\n4. CORTICOIDE SISTÊMICO (1ª linha em acometimento sistêmico):\n• Prednisona 1 mg/kg/dia VO (até 80mg/dia)\n• OU Metilprednisolona 1 mg/kg/dia IV (forma grave/incapaz de VO)\n• PULSOTERAPIA (forma muito grave): Metilprednisolona 500–1000mg IV/dia × 3 dias\n• Início de efeito: 24–48h (melhora de febre, exantema)\n• Manter dose plena por 1–2 semanas\n• Desmame LENTO (8–12 semanas) — recaídas frequentes com desmame rápido\n\nINDICAÇÕES DE CORTICOIDE:\n• Acometimento sistêmico (qualquer órgão)\n• Hepatite com transaminases > 5× LSN\n• Pneumonite\n• Miocardite\n• Eosinofilia > 5000\n• Eritrodermia\n\n5. ALTERNATIVAS (corticoide refratário ou contraindicado):\n• Imunoglobulina IV (IVIG) 1–2g/kg em 2–5 dias (controverso)\n• Ciclosporina 3–5 mg/kg/dia (poupador de corticoide)\n• Ganciclovir (se reativação documentada de HHV-6)\n• Plasmaférese (casos extremos)\n\n6. TRATAMENTO DAS COMPLICAÇÕES:\n• Hepatite: monitorar, considerar transplante se fulminante (rara — < 5%)\n• Nefrite intersticial: hidratação, evitar nefrotóxicos\n• Miocardite: monitorar troponina, ECO seriado, beta-bloqueador conforme indicação\n• Tireoidite (tardia): seguimento de TSH por meses\n\n7. NÃO DAR:\n• Outros antibióticos sem necessidade (risco de reação cruzada)\n• Anticonvulsivantes aromáticos da mesma classe (se carbamazepina era a causa, evitar fenitoína)\n\n8. DOCUMENTAÇÃO:\n• Cartão de alergia\n• Pulseira de identificação\n• Comunicar atenção básica e farmácias\n• Notificar ANVISA (VigiMed)" },
      { id: "followup", title: "Acompanhamento", content: "Hospitalar:\n• Reavaliação diária: pele, sinais vitais, hepato/renal/cardiovascular\n• Resolução lenta (semanas)\n\nAlta com prednisona em desmame:\n• Reduzir 10% a cada 1–2 semanas\n• 8–12 semanas total\n• Recidiva é comum com desmame rápido — voltar à dose efetiva e desmamar mais lento\n\nSEGUIMENTO LONGO PRAZO (importante!):\n• TSH a cada 1, 3, 6 meses (tireoidite tardia)\n• Glicemia (DM tipo 1 tardio)\n• Função hepática até normalização\n• Despertar atenção para sintomas de novas autoimunidades\n• Acompanhamento dermatológico por 12 meses no mínimo\n\nORIENTAR PACIENTE:\n• Lista de medicamentos a EVITAR para vida toda\n• Apresentar lista em qualquer atendimento médico\n• Atenção a anticonvulsivantes (reação cruzada)\n• Sintomas de alarme: febre, exantema, dor abdominal, icterícia" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "Prednisona 1 mg/kg/dia:\n• Adulto de 70kg → 60–80mg VO 1x/dia (manhã)\n• Dividir em 2 doses se efeitos colaterais\n• Manter até melhora clínica e laboratorial completa\n• Desmamar 10% a cada 1–2 semanas\n\nMetilprednisolona pulso (forma fulminante):\n• 1g IV/dia em 250mL SF em 60 min × 3 dias\n• Depois 1 mg/kg/dia oral\n• Atenção: hiperglicemia, hipocalemia, infecção, úlcera GI" },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: DRESS COM ACOMETIMENTO SISTÊMICO\n\n1. SUSPENDER MEDICAMENTO CAUSADOR IMEDIATAMENTE\n2. INTERNAÇÃO\n3. Prednisona 1mg/kg/dia VO (ex.: 70kg → 60mg/dia em jejum)\n   OU Metilprednisolona 1mg/kg/dia IV (se VO impossível)\n4. SF 0,9% 150–200mL/h IV (hidratação)\n5. Cuidados de pele: vaselina + curativo não aderente\n6. Cabeceira 30°\n7. Enoxaparina 40mg SC 1x/dia\n8. Omeprazol 40mg IV 1x/dia\n9. Profilaxia HSV/CMV em corticoide alta dose: aciclovir 400mg VO 8/8h\n10. Anti-histamínico para prurido: Loratadina 10mg VO 1x/dia\n\nLABORATÓRIO DIÁRIO:\n• Hemograma completo (eosinófilos, linfócitos atípicos)\n• ALT, AST, GGT, FA, bilirrubinas\n• Creatinina, ureia, EAS\n• Glicemia\n• Eletrólitos\n• CK, troponina\n• TSH (na admissão e na alta)\n\nADMISSÃO:\n• HHV-6, HHV-7 PCR (confirmar reativação)\n• EBV, CMV PCR\n• HIV, hepatite B/C\n• Cultura de pele se vesículas/pústulas\n\nCONTROLE:\n• ECG admissão e a cada 48h (miocardite)\n• Rx tórax (pneumonite)\n• ECO se troponina elevada\n\nDOCUMENTAÇÃO:\n• Notificação ANVISA VigiMed\n• Cartão de alergia\n• Educação ao paciente sobre drogas a evitar\n\n⚠️ Desmame de corticoide LENTO (8–12 semanas) — recaída comum\n⚠️ Tireoidite e diabetes podem surgir MESES depois — seguimento longo\n⚠️ Evitar anticonvulsivantes aromáticos relacionados (reação cruzada)" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Kardaun SH et al. Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS) — RegiSCAR. Br J Dermatol 2013.\n2. Shiohara T, Mizukawa Y. Drug-Induced Hypersensitivity Syndrome (DiHS)/DRESS. Allergol Int 2019.\n3. Cacoub P et al. The DRESS Syndrome — A Literature Review. Am J Med 2011.\n4. SBD. Consenso Brasileiro de Farmacodermia Grave. An Bras Dermatol 2022." }
    ]
  },
  {
    id: "fp-derm5-eritrodermia",
    title: "Eritrodermia",
    categoryId: "dermatology", category: "Dermatologia",
    tags: ["eritrodermia", "descamacao", "generalizada", "psoríase", "dermatite", "linfoma cutâneo"],
    sections: [
      { id: "intro", title: "Introdução", content: "Eritrodermia (dermatite esfoliativa) é estado de eritema e descamação generalizados que acomete > 90% da superfície corporal, com complicações sistêmicas potencialmente fatais — distúrbio termorregulatório, perdas hídricas e proteicas, insuficiência cardíaca de alto débito, infecção secundária. Mortalidade de 18–64% por sepse, ICC, falência multiorgânica. É emergência dermatológica que requer internação.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026." },
      { id: "def", title: "Definição", content: "Eritrodermia: eritema generalizado (> 90% da superfície corporal) com descamação variável.\n\nCausas (em ordem de frequência):\n• Exacerbação de dermatose preexistente (50%):\n  — Psoríase eritrodérmica\n  — Dermatite atópica\n  — Dermatite seborreica\n  — Pênfigo foliáceo\n• Reação a droga (30%):\n  — Anticonvulsivantes\n  — Alopurinol\n  — Antibióticos\n• Linfoma cutâneo de células T (Síndrome de Sézary — 5–10%)\n• Idiopática (10–20%)\n\nGravidade depende de:\n• Extensão e velocidade de instalação\n• Comorbidades\n• Idade (idoso > criança > adulto jovem)\n• Causa subjacente" },
      { id: "screening", title: "Rastreamento e Identificação", content: "Identificar imediatamente:\n• Paciente com eritema generalizado descamativo\n• 'Vermelhão de cabeça aos pés'\n• Calafrios, hipotermia paradoxal\n• Edema generalizado\n\nINVESTIGAR CAUSA:\n• História dermatológica prévia (psoríase? eczema?)\n• Drogas iniciadas nos últimos 2 meses\n• Idade (idoso → linfoma cutâneo? droga? psoríase?)\n• Sintomas constitucionais (febre, perda de peso → linfoma)\n• Linfadenopatia (linfoma? droga?)\n\nSINAIS DE ALERTA:\n• Distúrbio hemodinâmico\n• Hipotermia\n• Insuficiência cardíaca de alto débito\n• Sepse\n• Distúrbio eletrolítico\n• Hipoalbuminemia" },
      { id: "etiology", title: "Etiologia", content: "Dermatose subjacente exacerbada (50%):\n• Psoríase (mais comum)\n• Dermatite atópica\n• Dermatite seborreica\n• Pênfigo foliáceo, penfigoide bolhoso\n• Eczema de contato disseminado\n\nFarmacodermia (30%):\n• Anticonvulsivantes (carbamazepina, fenitoína, fenobarbital, lamotrigina)\n• Alopurinol\n• Antibióticos (penicilinas, sulfonamidas, vancomicina)\n• AINE\n• Antimaláricos\n• IECA, captopril\n• Sais de ouro\n• Carbamazepina\n\nLinfoma cutâneo (5–10%):\n• Síndrome de Sézary (variante leucêmica de micose fungoide)\n• Linfoma cutâneo de células T (CTCL)\n• Linfocitose periférica > 1000 com células atípicas\n\nIdiopática (10–20%):\n• Diagnóstico de exclusão após investigação completa" },
      { id: "clinical", title: "Apresentação Clínica", content: "Pele:\n• Eritema generalizado (cabeça aos pés)\n• Descamação variável: fina, lamelar, ou em escamas grandes\n• Edema marcado (especialmente face, mãos, pés)\n• Liquenificação tardia\n• Eclrópio (eversão das pálpebras por edema)\n• Alopecia difusa, distrofia ungueal\n• Prurido intenso\n\nManifestações sistêmicas:\n• Calafrios e tremor (perda de calor)\n• Hipotermia paradoxal\n• Taquicardia, taquipneia\n• Hipotensão (perdas, baixo débito)\n• Edema periférico (hipoalbuminemia)\n• Insuficiência cardíaca de alto débito (shunting cutâneo)\n• Linfadenopatia (dermopática ou linfoma)\n• Hepatomegalia, esplenomegalia (em linfoma)\n\nLABORATÓRIO comum (mesmo sem complicação):\n• Hipoalbuminemia\n• Anemia (crônica)\n• Eletrólitos alterados\n• Hipergamaglobulinemia\n• Eosinofilia (droga, linfoma)\n• VHS, PCR elevados\n• Função renal e hepática alteradas\n\nCOMPLICAÇÕES POTENCIALMENTE FATAIS:\n• Sepse (pele desnudada — porta de entrada)\n• ICC de alto débito (especialmente cardiopatia prévia)\n• Distúrbio hidroeletrolítico grave\n• Hipotermia\n• Trombose (estado pró-coagulante)\n• Síndrome de Sézary com falência medular" },
      { id: "diagnosis", title: "Diagnóstico", content: "Diagnóstico CLÍNICO (eritema generalizado descamativo)\n\nInvestigação da CAUSA:\n• História detalhada (medicamentos, dermatose prévia)\n• Exame físico completo (linfadenopatia? hepatoesplenomegalia?)\n• BIÓPSIA DE PELE (em geral inespecífica, mas pode orientar):\n  — Múltiplas biópsias em locais diferentes\n  — Imuno-histoquímica para linfoma\n• Hemograma com diferencial (linfócitos atípicos, células de Sézary)\n• Esfregaço periférico (células de Sézary se > 1000/mm³ — linfoma!)\n• Imunofenotipagem por citometria (CD4/CD8, marcadores de Sézary)\n• Eletroforese de proteínas\n• Provas reumatológicas (ANA, FR)\n\nLaboratório de gravidade:\n• Hemograma\n• Eletrólitos (Na+, K+, Ca++)\n• Albumina, proteínas totais\n• Função renal, hepática\n• PCR, procalcitonina\n• Hemoculturas (se febre/sepse)\n• Cultura de pele (S. aureus, MRSA?)\n• Glicemia (estado hipercatabólico)\n\nImagem (linfoma):\n• TC pescoço, tórax, abdome e pelve (linfadenopatia, esplenomegalia)\n• PET-CT" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "• SSJ/NET (mucosa muito acometida, descolamento epidérmico, droga típica)\n• DRESS (acometimento sistêmico orgânico, eosinofilia, droga típica)\n• Pênfigo foliáceo (vesículas que se rompem facilmente)\n• Síndrome do choque tóxico (descamação tardia, hipotensão, febre)\n• Síndrome de Sézary (linfoma — investigar sempre em eritrodermia idiopática crônica)\n• Pitiríase rubra pilar (placas alaranjadas, ilhas de pele poupada)" },
      { id: "conduct", title: "Conduta", content: "MEDIDAS DE SUPORTE — TODAS OBRIGATÓRIAS:\n\n1. INTERNAÇÃO (UTI se instabilidade):\n• Ambiente termoregulado (28–30°C)\n• Cobertores aquecidos\n• Monitorização hemodinâmica\n\n2. SUSPENSÃO DE DROGAS SUSPEITAS:\n• Suspender todos os medicamentos não essenciais iniciados nos últimos 2 meses\n• Documentar como alergia\n\n3. HIDRATAÇÃO E ELETRÓLITOS:\n• SF 0,9% IV: 100–200 mL/h (ajustar com diurese, peso, balanço)\n• Reposição de K+, Mg++, fosfato conforme necessidade\n• Albumina 20% 100mL IV se hipoalbuminemia grave (< 2,0)\n\n4. CUIDADOS DE PELE:\n• Banho com água morna 2x/dia (sem sabonete agressivo)\n• Vaselina líquida ou cremes oleosos generosamente após o banho\n• Compressas frias úmidas para áreas exsudativas\n• Curativos não aderentes\n• Lubrificação labial (vaselina)\n\n5. CONTROLE DA INFECÇÃO:\n• Hemoculturas 2 amostras se febre\n• Cultura de pele (impetiginização?)\n• ATB empírico se sepse: Vancomicina + Cefepima (cobrir MRSA + gram-negativos)\n• NÃO usar profilaxia rotineira (resistência)\n\n6. NUTRIÇÃO:\n• Estado hipercatabólico\n• Nutrição enteral precoce\n• Proteína 1,5–2g/kg/dia\n• Suplemento (perdas pela pele)\n\n7. ANALGESIA E PRURIDO:\n• Antihistamínicos sedativos à noite: hidroxizina 25–50mg VO 8/8h\n• Loratadina 10mg VO 1x/dia\n• Analgesia: Dipirona 1g IV 6/6h\n\nTRATAMENTO ESPECÍFICO POR CAUSA:\n\nPSORÍASE ERITRODÉRMICA:\n• Ciclosporina 3–5 mg/kg/dia (resposta rápida)\n• Acitretina 25–50mg/dia (mais lenta)\n• Metotrexato 7,5–15mg/semana\n• Biológicos: infliximabe, ustequinumabe, secukinumabe (especializado)\n• EVITAR corticoide sistêmico (rebote ao retirar — pode precipitar pustulose generalizada)\n\nFARMACODERMIA / DRESS:\n• Ver protocolo DRESS\n• Corticoide sistêmico (Prednisona 1mg/kg/dia)\n\nDERMATITE ATÓPICA / ECZEMA:\n• Corticoide tópico potente\n• Tacrolimus tópico\n• Ciclosporina 3–5 mg/kg/dia\n• Dupilumabe (biológico)\n\nLINFOMA CUTÂNEO (Sézary):\n• Tratamento oncológico especializado\n• Bexaroteno, fototerapia, biológicos\n• Quimioterapia se avançado\n\nIDIOPÁTICA:\n• Corticoide sistêmico em prednisona 0,5–1mg/kg/dia\n• Imunossupressores se refratário\n\n8. PROFILAXIA TEP:\n• Enoxaparina 40mg SC 1x/dia (estado pró-trombótico)" },
      { id: "followup", title: "Acompanhamento", content: "Hospitalar prolongado (geralmente 2–4 semanas):\n• Monitorização hemodinâmica e nutricional\n• Resolução cutânea lenta\n• Identificação da causa\n• Tratamento específico\n\nAlta apenas com:\n• Estabilidade hemodinâmica\n• Causa identificada e tratada\n• Eritema regredindo\n• Recuperação nutricional\n• Plano de seguimento\n\nSeguimento ambulatorial:\n• Dermatologia (semanal por 1 mês, depois mensal)\n• Especialista da causa (reumato, onco-hemato, etc.)\n\nMonitorar:\n• Recidiva\n• Sequelas: distrofias ungueales, alopecia, hiperpigmentação\n• Evolução para linfoma (se inicialmente idiopática)" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "Ciclosporina (psoríase eritrodérmica):\n• 3–5 mg/kg/dia ÷ 2 doses\n• Resposta em 1–2 semanas\n• Monitorar: PA, creatinina, K+\n• Manter por 3–6 meses, transição para tratamento sistêmico crônico\n\nCorticoide (formas SEM psoríase):\n• Prednisona 0,5–1 mg/kg/dia\n• Pulsoterapia em formas muito graves: metilprednisolona 250–500mg IV/dia × 3 dias\n• ATENÇÃO: NÃO usar em psoríase (rebote!)\n\nVaselina líquida:\n• Aplicar generosamente após banho\n• Sem perfume\n• Cobrir TODA a superfície corporal" },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: ERITRODERMIA COM REPERCUSSÃO SISTÊMICA\n\n1. INTERNAÇÃO + ambiente aquecido (28–30°C)\n2. Suspender medicamentos não essenciais (suspeitos de farmacodermia)\n3. SF 0,9% 150–200mL/h IV (manutenção)\n4. Albumina 20% 100mL IV se albumina < 2,0 g/dL\n5. Reposição de K+, Mg++, fosfato (conforme laboratório)\n6. CUIDADOS DE PELE:\n   • Banho com água morna 2x/dia (sem sabonete agressivo)\n   • Vaselina líquida em TODA a pele após banho\n   • Compressas frias úmidas em áreas exsudativas\n   • Vaselina nos lábios\n\n7. PRURIDO:\n   • Hidroxizina 25mg VO 8/8h\n   • Loratadina 10mg VO 1x/dia\n\n8. ANALGESIA: Dipirona 1g IV 6/6h\n\n9. PROFILAXIA TEP: Enoxaparina 40mg SC 1x/dia\n\n10. PROFILAXIA ÚLCERA STRESS: Omeprazol 40mg IV 1x/dia\n\n11. SE FEBRE/SUSPEITA DE SEPSE:\n    • Hemoculturas 2 amostras\n    • Cultura de pele\n    • Vancomicina 25mg/kg IV + Cefepima 2g IV 8/8h\n\n12. TRATAMENTO ESPECÍFICO:\n    PSORÍASE: Ciclosporina 4mg/kg/dia VO (dividir em 2 doses)\n    FARMACODERMIA/IDIOPÁTICA: Prednisona 0,5–1mg/kg/dia VO\n    LINFOMA: especializado (oncohematologia)\n\n13. NUTRIÇÃO:\n    • Dieta hiperproteica\n    • Suplemento oral 2x/dia (whey 25g)\n    • Avaliar SNE se ingesta < 75%\n\n14. LABORATÓRIO DIÁRIO:\n    • Hemograma, função renal e hepática, eletrólitos, albumina, PCR\n    • Hemoculturas se febre\n\n15. INVESTIGAÇÃO:\n    • Biópsia de pele (múltiplos sítios)\n    • Esfregaço periférico (células de Sézary)\n    • Imunofenotipagem se células atípicas\n    • TSH, ANA, FR\n    • Sorologias HIV, hepatites\n\n⚠️ NÃO usar corticoide sistêmico em psoríase eritrodérmica (rebote)\n⚠️ Eritrodermia idiopática persistente — investigar LINFOMA\n⚠️ Mortalidade alta (18–64%) — cuidado integrado intensivo" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Mistry N et al. Erythroderma — Acute Skin Failure. Br J Dermatol 2015.\n2. Sigurdsson V et al. Erythroderma — A Clinical Study of 32 Cases. Br J Dermatol 1996.\n3. Rothe MJ et al. Life-Threatening Erythroderma. Dermatol Clin 2000.\n4. SBD. Consenso Brasileiro de Eritrodermia. An Bras Dermatol 2022." }
    ]
  },
  {
    id: "fp-derm-18-03",
    title: "Pênfigo Vulgar Extenso",
    categoryId: "dermatology", category: "Dermatologia",
    tags: ["pênfigo vulgar", "doença bolhosa autoimune", "nikolsky", "corticoide", "rituximabe"],
    sections: [
      { id: "intro", title: "Introdução", content: "Pênfigo vulgar é doença bolhosa autoimune potencialmente fatal causada por autoanticorpos contra desmogleínas 3 e 1 dos desmossomos epidérmicos, resultando em acantólise intraepidérmica. Antes da era dos corticoides, mortalidade era de 70–100%. Atualmente, com corticoide + imunossupressores e rituximabe, mortalidade é de 5–10%, principalmente por complicações infecciosas. Acomete pele e mucosas, sendo o envolvimento oral a manifestação inicial em 50–70% dos casos.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026 · International Pemphigus Guidelines 2020." },
      { id: "def", title: "Definição", content: "Doença bolhosa autoimune com autoanticorpos IgG contra:\n• Desmogleína 3 (Dsg3) — mucosa\n• Desmogleína 1 (Dsg1) — pele\n\nSubtipos:\n• Pênfigo vulgar mucocutâneo: envolvimento de pele + mucosa (Dsg1 + Dsg3)\n• Pênfigo vulgar predominantemente mucoso: apenas mucosa (apenas Dsg3)\n• Pênfigo foliáceo: apenas pele, lesões superficiais (apenas Dsg1) — endêmico no Brasil ('Fogo Selvagem' — região Centro-Oeste)\n• Pênfigo paraneoplásico: associado a neoplasia (linfoma, timoma)\n• Pênfigo induzido por droga (penicilamina, captopril)\n\nClassificação de gravidade:\n• Leve: < 10% superfície corporal\n• Moderado: 10–30%\n• Grave/extenso: > 30%, mucosas extensas\n\nMortalidade: 5–10% com tratamento adequado" },
      { id: "screening", title: "Rastreamento e Identificação", content: "SUSPEITAR em:\n• Erosões orais persistentes (semanas-meses) sem cicatrização\n• Bolhas flácidas em pele que se rompem facilmente\n• Sinal de Nikolsky POSITIVO (deslizamento da pele à pressão tangencial)\n• Idoso ou meia-idade (40–60 anos)\n• Origem mediterrânea, judaica asquenaze\n• Dor oral intensa, disfagia, recusa alimentar\n\nMUCOSAS SÃO PRIMEIRO ENVOLVIMENTO em 50–70%:\n• Oral (mais comum): erosões dolorosas, língua, gengiva, mucosa jugal\n• Faríngea, laríngea\n• Esôfago\n• Conjuntival\n• Nasal\n• Genital, anal\n\nEMERGÊNCIA quando:\n• > 30% superfície corporal\n• Sepse\n• Desnutrição (incapacidade de comer)\n• Comprometimento de via aérea (laríngeo)\n• Distúrbio hidroeletrolítico" },
      { id: "etiology", title: "Etiologia", content: "Autoimune:\n• Autoanticorpos IgG contra desmogleínas 3 e 1\n• Acantólise (perda de adesão entre ceratinócitos)\n• Bolha intraepidérmica suprabasal\n\nFatores predisponentes:\n• Genética: HLA-DRB1*04, DRB1*14, DQB1*05:03 (judeus asquenazes, mediterrâneos)\n• Idade: pico 40–60 anos\n• Sem predileção por sexo\n\nGatilhos possíveis:\n• Drogas: penicilamina, captopril, IECA, AINE\n• Infecções (HHV-8?)\n• Estresse\n• UV\n• Pesticidas (pênfigo foliáceo endêmico)\n• Picada de inseto (em foliáceo brasileiro)" },
      { id: "clinical", title: "Apresentação Clínica", content: "Lesões mucosas (primeiro envolvimento — 50–70%):\n• Erosões dolorosas em boca, gengiva, língua, mucosa jugal, palato\n• Aspecto irregular, com bordas irregulares\n• Dor intensa → recusa alimentar → desnutrição\n• Pode acometer faringe, laringe (disfonia), esôfago\n• Conjuntiva: erosões, simbléfaro\n• Genital: erosões dolorosas\n\nLesões cutâneas:\n• Bolhas flácidas (frágeis) em pele NORMAL ou eritematosa\n• Rompem facilmente → erosões\n• Sinal de Nikolsky POSITIVO: deslizamento da pele à pressão tangencial\n• Sinal de Asboe-Hansen: bolha se expande com pressão\n• Distribuição: face, couro cabeludo, tronco, axilas, virilhas, área de pressão\n• Não há prurido (diferente do penfigoide)\n\nCOMPLICAÇÕES:\n• Sepse (pele desnudada = porta de entrada para bactérias)\n• Desidratação, distúrbio eletrolítico\n• Hipoalbuminemia\n• Pneumonia (aspiração — disfagia)\n• Trombose venosa\n• Efeitos adversos de corticoide alta dose (infecção, DM, osteoporose)\n• Mortalidade principalmente por SEPSE" },
      { id: "diagnosis", title: "Diagnóstico", content: "1. CLÍNICO:\n• Bolhas flácidas, sinal de Nikolsky, erosões mucosas\n\n2. BIÓPSIA DE PELE (lesão recente, pele perilesional):\n• Histopatologia: acantólise suprabasal, células acantolíticas\n• Vesícula intraepidérmica\n\n3. IMUNOFLUORESCÊNCIA DIRETA (IFD) — padrão-ouro:\n• Biópsia de pele perilesional (não da bolha)\n• Depósito de IgG e C3 em padrão 'rede de pesca' (intercelular) na epiderme\n\n4. IMUNOFLUORESCÊNCIA INDIRETA (IFI):\n• Detecta autoanticorpos circulantes\n• Substrato: esôfago de macaco\n• Mais útil para monitorar atividade da doença\n\n5. ELISA para Dsg3 e Dsg1:\n• Quantifica autoanticorpos\n• Útil para acompanhamento da resposta ao tratamento\n• Dsg3 alto: doença mucosa ativa\n• Dsg1 alto: doença cutânea ativa\n\nLaboratório adicional:\n• Hemograma\n• Eletrólitos, albumina, função renal e hepática\n• Glicemia (uso de corticoide)\n• Sorologias HIV, HBV, HCV (antes de imunossupressor)\n• PPD ou IGRA (TB latente — antes de imunossupressor)\n• Calcio, vitamina D (osteoporose por corticoide)\n• HLA tipagem (centros especializados)" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "• Penfigoide bolhoso (bolhas TENSAS, idoso, prurido, Dsg1/Dsg3 negativos, BP180+)\n• Pênfigo foliáceo (apenas pele, sem mucosa — endêmico no Brasil)\n• SSJ/NET (eritema confluente, descolamento epidérmico amplo, droga)\n• Eritema multiforme (alvos, drogas/HSV)\n• Estomatite aftosa recorrente (úlceras isoladas, cura espontânea)\n• Líquen plano oral (placas reticulares brancas, sem bolhas)\n• Herpes oral (vesículas agrupadas, dolorosas, recorrentes)\n• Doença IgA linear\n• Pênfigo paraneoplásico (associado a neoplasia)" },
      { id: "conduct", title: "Conduta", content: "1. INTERNAÇÃO se:\n• > 10% superfície corporal\n• Envolvimento mucoso extenso (incapaz de se alimentar)\n• Desnutrição\n• Suspeita de sepse\n• Comprometimento de via aérea\n\n2. CUIDADOS DE SUPORTE:\n• Cuidados de pele: vaselina, curativos não aderentes\n• Higiene oral suave: bochechos com SF morno\n• Anestésico tópico oral: lidocaína 2% gel antes de comer\n• Dieta líquida/pastosa fria\n• Nutrição: SNE se necessário\n• Hidratação IV\n• Profilaxia TEP\n\n3. TRATAMENTO DE PRIMEIRA LINHA (corticoide sistêmico):\n• Prednisona 1mg/kg/dia VO (até 1,5 mg/kg/dia em casos graves)\n• OU Metilprednisolona 1mg/kg/dia IV (se VO impossível)\n• PULSOTERAPIA em casos muito graves: Metilprednisolona 500–1000mg IV/dia × 3 dias\n\n4. POUPADOR DE CORTICOIDE (iniciar precocemente):\n• Azatioprina 1,5–2,5 mg/kg/dia VO\n  — Verificar TPMT antes (risco de mielotoxicidade se baixa)\n• Micofenolato mofetil 2g/dia VO ÷ 2 doses (alternativa)\n• Ciclofosfamida (refratário)\n\n5. RITUXIMABE (anti-CD20) — INDICADO COMO PRIMEIRA LINHA EM CASOS MODERADOS-GRAVES:\n• 375 mg/m² IV semanal × 4 doses (esquema linfoma)\n• OU 1g IV nos dias 0 e 14 (esquema artrite reumatoide)\n• Eficácia superior em ensaios clínicos\n• Permite redução rápida do corticoide\n• Indicações: doença grave, refratário a corticoide, intolerância ao corticoide\n• Pré-medicação: paracetamol, anti-histamínico, corticoide\n• Atenção: reação infusional, infecção, reativação HBV\n\n6. IMUNOGLOBULINA IV (IVIG):\n• 2g/kg em 3–5 dias por mês\n• Refratário, gestante (corticoide alta dose contraindicado)\n• Adjuvante\n\n7. PROFILAXIAS (corticoide + imunossupressor):\n• Pneumocystis: SMX-TMP 960mg VO 3x/semana\n• Osteoporose: cálcio + vitamina D + bifosfonato\n• Úlcera de stress: omeprazol\n• Vacinação: pneumocócica, influenza (NÃO vivas — vacinar ANTES de imunossupressor)\n• Glicemia (controle DM induzido)\n• Profilaxia TEP enquanto hospitalizado\n• Rastrear TB latente antes (PPD, IGRA)\n• Rastrear HBV antes de rituximabe (risco de reativação)\n\n8. CUIDADO COM INFECÇÃO SECUNDÁRIA:\n• Cultura de pele\n• Hemoculturas se febre\n• ATB empírico se sepse: vancomicina + cefepima\n• Suspender imunossupressor temporariamente se sepse grave\n\n9. EVITAR:\n• Trauma cutâneo\n• Adesivos diretamente na pele (lesão por arrancamento)\n• Banho com sabão agressivo\n• Calor excessivo\n• Drogas conhecidas como desencadeantes (penicilamina, captopril)" },
      { id: "followup", title: "Acompanhamento", content: "Monitorar resposta:\n• Clínica: novas bolhas? cicatrização?\n• Dsg3 e Dsg1 ELISA a cada 1–3 meses\n• Sinal de Nikolsky\n\nFases de tratamento:\n1. Controle: novas bolhas cessam (semanas)\n2. Consolidação: 80% das lesões cicatrizam, 2 semanas sem novas (manter dose 2 semanas)\n3. Manutenção: redução gradual do corticoide ao longo de meses\n4. Remissão: sem lesões com baixa dose ou sem corticoide\n\nDESMAMA CORTICOIDE LENTA:\n• Reduzir 10–20% a cada 2–4 semanas\n• Acelerar uma vez no manutenção (5mg a cada mês)\n• Recidiva: voltar à dose anterior\n\nSEGUIMENTO LONGO PRAZO:\n• Dermatologista mensal-trimestral\n• Densitometria óssea anual\n• Glicemia, função renal, hemograma a cada 1–3 meses\n• Catarata, glaucoma (uso prolongado de corticoide)\n• Avaliação odontológica periódica\n• Vacinação atualizada\n• Pesquisa de neoplasia se idade > 60 (paraneoplásico)" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "Prednisona:\n• 1 mg/kg/dia VO (manhã, após café)\n• Aumentar para 1,5 mg/kg se sem resposta em 1 semana\n• Manter dose até controle (sem novas bolhas)\n• Reduzir 10% a cada 2 semanas até 20mg/dia\n• Depois 5mg a cada mês até suspensão (ao longo de 12–24 meses)\n\nRituximabe (preferido para doença moderada-grave):\n• 1g IV no dia 0 e dia 14 (esquema RA)\n• OU 375 mg/m² semanal × 4 (esquema linfoma)\n• Pré-medicar: paracetamol 1g + difenidramina 50mg + metilpred 100mg IV 30 min antes\n• Verificar HBsAg, anti-HBc, HIV antes\n• Eficácia melhor que corticoide isolado em ensaios\n• Reinfusão a cada 6–12 meses se recidiva" },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: PÊNFIGO VULGAR EXTENSO (> 30% SUPERFÍCIE)\n\n1. INTERNAÇÃO\n2. CUIDADOS DE PELE:\n   • Vaselina líquida em toda a pele 2x/dia\n   • Curativos não aderentes (Mepilex, espuma)\n   • Banho com SF morno (sem sabonete agressivo)\n\n3. CUIDADOS ORAIS:\n   • Bochechos com SF 0,9% morno 4x/dia\n   • Lidocaína 2% gel oral antes das refeições\n   • Clorexidina 0,12% bochecho (sem álcool) 2x/dia\n   • Higiene dental delicada (escova macia)\n\n4. NUTRIÇÃO:\n   • Dieta líquida/pastosa fria\n   • Suplemento oral (whey 25g 2x/dia)\n   • SNE se ingesta < 50% das necessidades\n\n5. HIDRATAÇÃO: SF 0,9% 150mL/h IV\n\n6. CORTICOIDE (1ª linha):\n   • Prednisona 1mg/kg/dia VO (manhã, após café)\n   • Ex.: 70kg → 60–80mg VO 1x/dia\n   • Se VO impossível: Metilprednisolona 1mg/kg/dia IV\n\n7. POUPADOR DE CORTICOIDE (iniciar precocemente):\n   • Azatioprina 50mg VO 1x/dia (aumentar conforme TPMT)\n   • OU Micofenolato mofetil 1g VO 12/12h\n\n8. RITUXIMABE (formas moderadas-graves — preferencial):\n   • 1g IV no dia 0 + dia 14\n   • Pré-medicar: Paracetamol 1g + Difenidramina 50mg + Metilpred 100mg IV 30 min antes\n\n9. PROFILAXIAS:\n   • SMX-TMP 960mg VO 3x/semana (Pneumocystis)\n   • Cálcio 1000mg + Vitamina D 1000 UI VO 1x/dia\n   • Omeprazol 40mg VO 1x/dia\n   • Enoxaparina 40mg SC 1x/dia (TEP)\n\n10. CONTROLE DE INFECÇÃO:\n    • Cultura de pele basal\n    • Hemoculturas se febre\n    • Se sepse: Vancomicina 25mg/kg IV + Cefepima 2g IV 8/8h\n\n11. EXAMES BASAIS:\n    • Hemograma, função renal e hepática, eletrólitos, albumina, glicemia, HbA1c\n    • Sorologias HIV, HBV (HBsAg, anti-HBc, anti-HBs), HCV\n    • PPD ou IGRA (TB latente)\n    • Vitamina D, cálcio, fósforo, PTH\n    • Dsg3 e Dsg1 ELISA (basal)\n    • TPMT antes da azatioprina\n    • Densitometria óssea\n\n12. CONFIRMAÇÃO DIAGNÓSTICA (se ainda não feita):\n    • Biópsia de pele para histopatologia\n    • Biópsia perilesional para imunofluorescência direta\n    • IFI sérica\n    • ELISA Dsg3 e Dsg1\n\n⚠️ Mortalidade principal por SEPSE — vigilância de infecção rigorosa\n⚠️ Rituximabe é evidência mais robusta — considerar como 1ª linha em doença moderada-grave\n⚠️ Desmame de corticoide LENTO (12–24 meses) — recidiva frequente" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Joly P et al. First-line Rituximab vs Standard Corticosteroid Therapy in Pemphigus. Lancet 2017.\n2. Murrell DF et al. International Consensus Statement on Pemphigus Definitions. J Am Acad Dermatol 2020.\n3. Joly P et al. International Pemphigus Guidelines — Updated 2020. JEADV 2020.\n4. SBD. Consenso Brasileiro de Pênfigo. An Bras Dermatol 2022." }
    ]
  },
  {
    id: "fp-derm-18-09",
    title: "Síndrome de Pele Escaldada Estafilocócica (SSSS)",
    categoryId: "dermatology", category: "Dermatologia",
    tags: ["SSSS", "Staphylococcus aureus", "toxina esfoliativa", "criança", "Ritter", "Nikolsky"],
    sections: [
      { id: "intro", title: "Introdução", content: "A Síndrome de Pele Escaldada Estafilocócica (SSSS — Staphylococcal Scalded Skin Syndrome) é doença mediada por toxinas esfoliativas (ETA, ETB) produzidas por Staphylococcus aureus, causando descolamento intraepidérmico superficial. Acomete principalmente crianças < 5 anos (mais comum em lactentes) e adultos imunossuprimidos. Em crianças, mortalidade é baixa (< 4%); em adultos com comorbidades, pode chegar a 60%. Diferencia-se de NET por idade, pele perilesional, mucosa preservada e ausência de droga gatilho.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026." },
      { id: "def", title: "Definição", content: "Doença cutânea aguda causada por toxinas esfoliativas estafilocócicas:\n• ETA (mais comum), ETB, ETD\n• Clivam desmogleína 1 (Dsg1) → acantólise intragranular → bolha subcorneal\n\nFormas clínicas:\n• Generalizada (Ritter doença, em recém-nascidos)\n• Localizada (impetigo bolhoso — apenas no local da infecção)\n• Sépsis com SSSS (forma mais grave)\n\nDifere de NET:\n• SSSS: clivagem intragranular alta → epiderme superficial\n• NET: clivagem juncional → toda epiderme se descola\n• SSSS poupa mucosas (Dsg3 não afetada)\n• NET tem mucosa muito acometida\n\nMortalidade:\n• Criança: < 4%\n• Adulto (raro, geralmente imunocomprometido): 40–60%" },
      { id: "screening", title: "Rastreamento e Identificação", content: "SUSPEITAR em:\n• Criança < 5 anos (especialmente lactentes < 2 anos)\n• Adulto imunocomprometido com:\n  — Insuficiência renal crônica (toxina não eliminada)\n  — Imunossupressão (HIV, quimioterapia, transplante)\n  — Alcoolismo\n  — Diabetes\n\nApresentação típica:\n• Pródromos: febre, irritabilidade, mal-estar (12–24h)\n• Eritema iniciando em face, pescoço, área de fralda\n• Pele dolorosa ao toque\n• Bolhas flácidas\n• Sinal de Nikolsky POSITIVO\n• Descamação extensa em 24–48h\n• MUCOSAS PRESERVADAS (sinal-chave para diferenciar de NET!)\n• Conjuntivite estafilocócica frequente\n• Crostas peri-orais ('aspecto de farinha de pão')\n\nFOCO INFECCIOSO PRIMÁRIO:\n• Otorrinolaringológico (otite média, sinusite)\n• Conjuntivite\n• Piodermite\n• Coto umbilical (neonato)\n• Ferida cirúrgica\n• Faringite\n• Pneumonia\n• Frequentemente NÃO identificado o foco" },
      { id: "etiology", title: "Etiologia", content: "Staphylococcus aureus produtor de toxinas esfoliativas:\n• Grupo fágico II (cepas 71, 55, 3A, 3B, 3C, 113)\n• Produção de ETA (mais comum no Brasil), ETB, ETD\n\nMecanismo da toxina:\n• Cliva proteoliticamente a Dsg1 (proteína desmossomal)\n• Acantólise intragranular\n• Bolha subcorneal\n• Toxina circula sistemicamente desde foco distante (não precisa estar na pele!)\n\nPor que crianças e renal crônico?\n• Toxina é eliminada pelos rins\n• Criança: rim imaturo → não elimina bem\n• Adulto saudável: elimina rapidamente → não desenvolve SSSS\n• Renal crônico: não elimina → acúmulo\n• Adulto também tem anticorpos anti-toxina (proteção parcial)\n\nFOCO INFECCIOSO:\n• Pode ser distante da pele\n• Otorrinolaringológico (otite, sinusite, faringite)\n• Conjuntivite\n• Piodermite localizada\n• Umbigo (neonato)\n• Pneumonia estafilocócica\n• Endocardite, osteomielite\n• 50% dos casos: foco não identificado" },
      { id: "clinical", title: "Apresentação Clínica", content: "Fase prodrômica (12–24h):\n• Febre (38,5–40°C)\n• Irritabilidade, choro inconsolável (criança)\n• Mal-estar\n• Anorexia\n\nFase eritrodermica (24–48h):\n• Eritema iniciando em face, pescoço, axilas, virilha\n• 'Aparência queimada' generalizada\n• Pele dolorosa ao toque (paciente recusa colo!)\n• Crostas perí-orais e periculares (impetigo associado)\n• Conjuntivite (sem ulceração conjuntival — diferente de NET!)\n\nFase esfoliativa (3–5 dias):\n• Bolhas flácidas (frágeis)\n• Sinal de Nikolsky POSITIVO\n• Descamação em folhas ('papel molhado')\n• MUCOSAS PRESERVADAS (boca, olhos, genital normais)\n• Pode parecer 'queimadura'\n\nFase recuperação (7–14 dias):\n• Reepitelização rápida (epiderme só superficial)\n• Sem cicatriz (camada basal preservada)\n• Descamação contínua por dias\n\nCOMPLICAÇÕES:\n• Desidratação (perdas pela pele)\n• Distúrbio eletrolítico\n• Hipotermia\n• Sepse estafilocócica\n• Pneumonia\n• Celulite\n• Falência multiorgânica (adulto)\n\nLABORATÓRIO:\n• Leucocitose com neutrofilia\n• PCR elevado\n• Hemocultura: geralmente NEGATIVA (toxinemia, não bacteremia em criança)\n• Cultura do foco: pode ser positiva\n• Função renal (criança pequena, adulto)" },
      { id: "diagnosis", title: "Diagnóstico", content: "Diagnóstico CLÍNICO:\n• Criança com eritrodermia + bolhas flácidas + Nikolsky+ + mucosa preservada = SSSS\n\nBiópsia de pele (CONFIRMAÇÃO em dúvida):\n• Padrão-ouro para diferenciar de NET\n• SSSS: clivagem alta, intragranular (subcorneal)\n• NET: clivagem juncional, necrose de toda a epiderme\n• Biópsia de congelação rápida pode ajudar (resultado em horas)\n\nCultura:\n• Hemocultura (negativa em > 95% dos casos pediátricos — é toxinemia)\n• Cultura do foco (otorrinolaringológico, conjuntiva, ferida): pode isolar S. aureus\n• Cultura de pele em SSSS: GERALMENTE NEGATIVA (toxina, não bactéria, na pele)\n\nDiferenciação clínica de NET:\n| | SSSS | NET |\n|---|---|---|\n| Idade | Criança < 5 anos | Qualquer idade |\n| Trigger | Infecção stafilocócica | Droga |\n| Mucosa | Preservada | Muito acometida |\n| Nikolsky | + na pele eritematosa | + difuso |\n| Pele desnudada | Superficial | Total espessura |\n| Cicatrização | Rápida, sem cicatriz | Lenta |\n| Mortalidade | < 4% (criança) | 25–35% |\n\nLaboratório:\n• Hemograma, eletrólitos, função renal\n• Glicemia, gasometria\n• Hemocultura, urocultura, cultura do foco" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "• NET / SSJ (droga, mucosa acometida, todas as idades, mortalidade alta)\n• Eritema multiforme major (lesões em alvo, mucosa)\n• Queimadura (história de exposição)\n• Pênfigo vulgar (mais crônico, idoso, mucosa)\n• Dermatite atópica em exacerbação\n• Síndrome do choque tóxico (descamação tardia, hipotensão, febre)\n• Reação a droga generalizada\n• Doença de Kawasaki (febre + linfadenopatia + lábios secos + descamação periungual tardia)\n• Eritrodermia de qualquer causa" },
      { id: "conduct", title: "Conduta", content: "1. INTERNAÇÃO (sempre):\n• Ambiente similar a unidade de queimados (ambiente aquecido)\n• Monitorização\n• UTI se forma grave/adulto\n\n2. CUIDADOS DE PELE (suporte similar a queimadura):\n• Manuseio gentil\n• Vaselina liberalmente\n• Curativos não aderentes (Mepitel, Adaptic, Mepilex)\n• Banho diário com SF morno\n• Evitar adesivos\n• Posição que minimize pressão\n\n3. ANTIBIÓTICO ANTI-STAFILOCÓCICO (parenteral, OBRIGATÓRIO):\n\nCriança / adulto sem fator de risco para MRSA:\n• Oxacilina 100–200 mg/kg/dia ÷ 4–6/6h IV\n• OU Cefazolina 50–100 mg/kg/dia ÷ 8/8h IV\n• OU Cefalexina 50 mg/kg/dia ÷ 6/6h VO (se forma leve)\n\nSuspeita de MRSA (comunidade alto risco, falha terapêutica):\n• Vancomicina 60 mg/kg/dia ÷ 6/6h IV (criança)\n• Linezolida 10 mg/kg 8/8h IV (alternativa)\n• Clindamicina 30 mg/kg/dia ÷ 8/8h (CA-MRSA suscetível)\n\nADULTO IMUNOCOMPROMETIDO:\n• Vancomicina 30 mg/kg/dia ÷ 8/8h (MRSA suspeito)\n• OU Oxacilina 2g IV 4/4h (MSSA)\n• Considerar combinação com clindamicina 600mg IV 8/8h (inibe síntese de toxinas — anti-toxina)\n\nDURAÇÃO: 7–14 dias parenteral, depois oral se necessário\n\n4. CLINDAMICINA COMO ANTI-TOXINA:\n• Inibe síntese ribossomal de toxinas\n• Considerar associar em forma grave (criança grave, adulto)\n• Dose: 10–13 mg/kg 6/6h IV (criança), 600mg 8/8h IV (adulto)\n\n5. CUIDADOS DE SUPORTE:\n• Hidratação IV (perdas pela pele) — ajustar pelo peso e área acometida\n• Reposição de eletrólitos\n• Nutrição (estado catabólico)\n• Controle de dor: paracetamol, dipirona, opióides se grave\n• Profilaxia TEP em adolescente/adulto\n• Aquecimento ambiental\n\n6. PESQUISA E TRATAMENTO DO FOCO:\n• Exame ORL, fundoscopia, conjuntivas\n• Cultura de coto umbilical (RN), conjuntiva, otite\n• Pesquisar infecção materna se RN\n\n7. NÃO USAR:\n• Corticoide sistêmico (aumenta multiplicação bacteriana, sem benefício comprovado)\n• Sulfadiazina de prata (pode ser irritativa)\n• AINE (risco em criança com infecção)\n\n8. ISOLAMENTO DE CONTATO (precaução de gotículas/contato em surto neonatal)" },
      { id: "followup", title: "Acompanhamento", content: "Hospitalar:\n• Reavaliação diária\n• Resposta clínica em 24–48h (cessam novas bolhas)\n• Descamação contínua por dias\n• Reepitelização em 7–14 dias\n\nAlta:\n• Sem novas bolhas por 48h\n• Hidratação e nutrição estabelecidas\n• Concluir antibiótico oral em casa (cefalexina ou clindamicina)\n• Reavaliação ambulatorial em 1–2 semanas\n\nIDENTIFICAR FONTE DE TRANSMISSÃO (especialmente em surto neonatal):\n• Cultura nasal da mãe / cuidadores\n• Treinamento em higiene das mãos\n• Comunicação infecção hospitalar\n\nPROGNÓSTICO:\n• Criança: excelente (mortalidade < 4%)\n• Adulto: ruim (40–60% — quase sempre comorbidades graves)\n• Sem cicatrização cicatricial (epiderme superficial)" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "Oxacilina IV (1ª linha em criança sem MRSA):\n• 100–200 mg/kg/dia ÷ 4/6h (criança)\n• 2g IV 4/4h (adulto)\n• Trocar para cefalexina VO quando melhora\n• Total 7–14 dias\n\nClindamicina:\n• Como ANTI-TOXINA (inibe síntese)\n• 10–13 mg/kg 6/6h IV (criança)\n• 600mg IV 8/8h (adulto)\n• Associar com beta-lactâmico em formas graves\n\nVancomicina (MRSA):\n• 60 mg/kg/dia ÷ 6/6h IV (criança)\n• 30 mg/kg/dia ÷ 8/8h IV (adulto, monitorar vancocinemia)\n\nHidratação:\n• Considerar 1,5–2x manutenção (perdas pela pele)\n• Holliday-Segar: 100mL/kg primeiros 10kg + 50mL/kg próximos 10kg + 20mL/kg acima\n• Ajustar para diurese e peso" },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: SSSS GENERALIZADA (CRIANÇA)\n\n1. INTERNAÇÃO em quarto aquecido (28–30°C)\n2. HIDRATAÇÃO IV: Holliday-Segar + 20–50% extra (pela pele)\n   • Ex.: criança 15kg → 1250mL/dia + 30% = 1625mL/dia\n   • Inicialmente SF 0,9%, depois SG 5% + eletrólitos\n3. ANTIBIÓTICO:\n   • Oxacilina 200 mg/kg/dia IV ÷ 4 doses (ou 6 doses)\n   • + Clindamicina 13 mg/kg/dose IV 8/8h (anti-toxina) — considerar em forma grave\n   • Se suspeita MRSA: Vancomicina 60 mg/kg/dia IV ÷ 6/6h\n4. CUIDADOS DE PELE:\n   • Manuseio gentil (não puxar, não arrancar adesivos)\n   • Vaselina liberalmente em toda a pele 2x/dia\n   • Curativos não aderentes (Mepilex, Adaptic)\n   • Banho com SF morno 1x/dia\n5. ANALGESIA:\n   • Paracetamol 15 mg/kg VO/IV 6/6h\n   • Dipirona 25 mg/kg IV 6/6h (criança)\n   • Morfina 0,05–0,1 mg/kg IV SOS (dor intensa)\n6. MONITORIZAÇÃO: PA, FC, temperatura, débito urinário (peso fralda)\n7. EXAMES:\n   • Hemograma, PCR, eletrólitos, função renal\n   • Hemocultura (frequentemente negativa)\n   • Cultura de pele (geralmente negativa)\n   • Cultura do FOCO: orofaringe, conjuntiva, otite, umbigo (neonato)\n   • Biópsia de pele para congelação rápida se dúvida com NET\n8. AVALIAÇÃO OFTALMOLÓGICA (conjuntivite associada)\n9. AVALIAÇÃO ORL (otite, sinusite)\n\nADULTO IMUNOCOMPROMETIDO:\n• Vancomicina 25 mg/kg IV ataque, depois 15-20 mg/kg 8/8h\n• + Clindamicina 600 mg IV 8/8h\n• UTI se instabilidade hemodinâmica\n\nNÃO USAR: Corticoide sistêmico, AINE\n\n⚠️ Mucosas PRESERVADAS em SSSS (≠ NET) — sinal-chave de diferenciação\n⚠️ Hemocultura negativa não exclui — é toxinemia\n⚠️ Investigar foco em ORL, conjuntiva, umbigo (frequentemente perdido)\n⚠️ Adulto com SSSS = imunocompromisso — investigar" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Ladhani S. Recent Developments in Staphylococcal Scalded Skin Syndrome. Clin Microbiol Infect 2001.\n2. Patel GK et al. Staphylococcal Scalded Skin Syndrome. Lancet Infect Dis 2018.\n3. Hubiche T et al. Staphylococcal Scalded Skin Syndrome — Mortality. Pediatr Infect Dis J 2014.\n4. SBP/SBD. Consenso Brasileiro de SSSS. Rev Bras Dermatol 2022." }
    ]
  },
  {
    id: "fp-derm-18-06",
    title: "Pustulose Exantemática Generalizada Aguda (PEGA / AGEP)",
    categoryId: "dermatology", category: "Dermatologia",
    tags: ["PEGA", "AGEP", "pustulose", "farmacodermia", "neutrofilica", "exantematica"],
    sections: [
      { id: "intro", title: "Introdução", content: "PEGA (Pustulose Exantemática Generalizada Aguda, ou AGEP em inglês) é farmacodermia neutrofílica caracterizada por surgimento súbito de pústulas não-foliculares estéreis sobre eritema generalizado. Mortalidade é baixa (< 5%), mas pode ser confundida com infecções sistêmicas pústulosas, levando a tratamento antibiótico desnecessário. A suspensão do fármaco causal leva à resolução em 1–2 semanas. Sequência típica: febre + eritema + pústulas centenas a milhares em < 24h após exposição.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026 · EuroSCAR." },
      { id: "def", title: "Definição", content: "Farmacodermia aguda caracterizada por:\n• Múltiplas (centenas-milhares) de pústulas pequenas (1–2 mm) não-foliculares\n• Estéreis (cultura negativa)\n• Sobre base eritematosa generalizada\n• Início súbito (horas após exposição à droga)\n• Resolução em 1–2 semanas com descamação\n\nCritérios diagnósticos de EuroSCAR (≥ 8 pontos = definitiva):\n• Apresentação clínica: pústulas típicas (+2), eritema (+2), distribuição (+2)\n• Curso: febre > 38°C (+1), neutrofilia > 7000 (+1)\n• Histopatologia: pústula intra/subcorneal espongiforme com edema dérmico (+2)\n\nCausas:\n• Drogas (90%) — geralmente antibióticos (ampicilina, amoxicilina, macrolídeos)\n• Infecção viral (raramente)\n• Vacinação\n• Picada de inseto, exposição a mercúrio\n• Mutação IL-36RN (PEGA recorrente — autoinflamatória)\n\nMortalidade baixa (< 5%), geralmente em idoso com comorbidades" },
      { id: "screening", title: "Rastreamento e Identificação", content: "SUSPEITAR em:\n• Surgimento súbito de pústulas (horas) após droga (especialmente antibiótico)\n• Erupção micropostulosa generalizada\n• Localização preferencial em dobras (axilas, virilhas) e tronco superior\n• Febre + leucocitose com neutrofilia\n• Pode ter envolvimento mucoso leve (10–25%)\n• Edema facial leve\n\nCRONOLOGIA TÍPICA:\n• 24–72h após início da droga (mais rápido que SSJ/NET e DRESS)\n• Pústulas que coalescem para grandes áreas de descamação\n• Resolução em 7–14 dias após suspender droga\n\nDIFERENÇA COM PSORÍASE PUSTULOSA GENERALIZADA:\n• PEGA: cronologia com droga, sem psoríase prévia\n• Psoríase pustulosa: pode ser primária, geralmente com história de psoríase\n• Histopatologia muito similar\n• Genética: mutação IL-36RN em algumas formas (overlap)" },
      { id: "etiology", title: "Etiologia", content: "DROGAS (90% — em ordem de frequência):\n• Aminopenicilinas: ampicilina, amoxicilina (mais comum no Brasil)\n• Macrolídeos: claritromicina, azitromicina\n• Quinolonas: ciprofloxacino, levofloxacino\n• Diltiazem (cardiovascular mais associado)\n• Hidroxicloroquina\n• Sulfonamidas\n• Cefalosporinas\n• Terbinafina\n• Carbamazepina\n• Iohexol (contraste iodado)\n\nNão-medicamentosa:\n• Infecção viral (raramente — picornavírus, parvovírus B19)\n• Vacinação (em pediatria)\n• Mercúrio\n• Picada de aranha (esporádica)\n\nGenética:\n• Mutação IL-36RN: defeito no antagonista do receptor de IL-36 → forma recorrente, mais grave (overlap com psoríase pustulosa generalizada)" },
      { id: "clinical", title: "Apresentação Clínica", content: "Pródromo (horas):\n• Febre alta súbita (38,5–40°C)\n• Mal-estar\n• Possível prurido\n\nFase eritematosa-pustulosa:\n• Eritema escarlatiniforme generalizado iniciando em face e tronco\n• Centenas a milhares de pústulas pequenas (1–2 mm)\n• NÃO foliculares (diferencia de foliculite)\n• Surgem sobre eritema (não em pele normal)\n• Coalescem formando 'lagos de pus'\n• Sinal de Nikolsky pode ser positivo (pústulas se descolam)\n\nDistribuição:\n• Dobras (axilas, virilhas, pescoço, cotovelos) — clássico\n• Tronco superior\n• Face (edema palpebral, eritema malar)\n• Genital (raro)\n• Pode tornar-se eritrodérmica\n\nMucosas:\n• Leve envolvimento em 10–25%\n• Pústulas orais raras\n• Edema labial possível\n• MUITO MENOS que SSJ/NET ou DRESS\n\nFase descamativa (7–14 dias):\n• Pústulas secam\n• Descamação em folhas\n• Sem cicatriz\n• Pode haver pigmentação residual\n\nLABORATÓRIO:\n• Leucocitose com neutrofilia marcada (> 10.000)\n• PCR muito elevado\n• Eosinofilia leve em 30%\n• Função renal leve alterada (raramente IRA)\n• ALT/AST leve elevadas em alguns casos\n• Hipocalcemia transitória (raramente)\n\nDIFERENTE de DRESS:\n• PEGA: sem hepatite significativa, sem linfadenopatia massiva, mais rápido\n• DRESS: hepatite frequente, linfadenopatia, eosinofilia alta, 2–8 semanas após droga" },
      { id: "diagnosis", title: "Diagnóstico", content: "Diagnóstico CLÍNICO + histopatologia:\n\nCritérios EuroSCAR (mais usado):\n• Pústulas estéreis, pequenas, não-foliculares\n• Eritema base\n• Cronologia compatível com droga\n• Histopatologia compatível\n\nBiópsia de pele:\n• Pústula intraepidérmica espongiforme (subcorneal/intracorneal)\n• Edema da derme papilar\n• Infiltrado neutrofílico\n• Eosinófilos comuns\n• SEM necrose de queratinócitos extensa (≠ NET)\n• SEM acantólise (≠ pênfigo)\n\nCultura de pústula:\n• ESTÉRIL (cultura negativa) — confirma\n\nLaboratório:\n• Hemograma: leucocitose 15.000–30.000 com neutrofilia\n• PCR elevado\n• Função renal, hepática (leve)\n• Eletrólitos (cálcio, fósforo — pode haver hipocalcemia)\n• Cultura cutânea (descartar infecção)\n• Hemocultura (descartar sepse — geralmente negativa)\n\nINVESTIGAR:\n• Lista detalhada de medicamentos nas últimas 4 semanas (mais comum: < 72h)\n• Excluir psoríase pustulosa generalizada (história, biópsia similar)" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "• Psoríase pustulosa generalizada (von Zumbusch) — sem droga gatilho, história pessoal/familiar de psoríase, mais crônica/recorrente\n• Foliculite generalizada (pústulas foliculares, S. aureus)\n• Impetigo bolhoso (criança, S. aureus)\n• SSJ/NET (descolamento de pele, mucosa muito acometida)\n• DRESS (lento — 2–8 semanas, hepatite, eosinofilia, linfadenopatia)\n• Doença de Sneddon-Wilkinson (pustulose subcorneal — mais crônica)\n• Síndrome de Sweet (placas eritematosas dolorosas)\n• Infecção viral (varicela, herpes — vesículas, não pústulas micro)\n• Reação a picada de inseto" },
      { id: "conduct", title: "Conduta", content: "1. SUSPENSÃO IMEDIATA DO MEDICAMENTO SUSPEITO (medida principal):\n• Identificar droga (geralmente cronologia clara: < 72h)\n• Suspender e documentar como alergia\n• Notificar ANVISA VigiMed\n\n2. CUIDADOS DE SUPORTE:\n• Internação se: forma extensa, febre alta, comorbidades, idoso\n• Manejo ambulatorial se forma leve em paciente jovem saudável\n• Hidratação IV se febre + perdas\n• Cuidados de pele:\n  — Compressas frias úmidas\n  — Emolientes (vaselina líquida)\n  — Corticoide tópico potente (clobetasol propionato) em áreas inflamadas\n\n3. CONTROLE DA INFECÇÃO:\n• Cultura cutânea (excluir impetigo secundário)\n• Hemoculturas se febre alta (excluir sepse)\n• NÃO usar antibiótico empírico de rotina (cultura é estéril!)\n\n4. CORTICOIDE SISTÊMICO (NÃO obrigatório — PEGA tem boa resolução espontânea):\n• Prednisona 0,5–1 mg/kg/dia VO em casos extensos\n• Curso CURTO (3–10 dias)\n• Mais para conforto e acelerar resolução\n• Resolução em 1–2 semanas mesmo sem corticoide\n\n5. ANALGESIA E ANTIPIRÉTICO:\n• Paracetamol\n• Dipirona\n• EVITAR AINE (pode piorar; alguns AINE causam PEGA)\n\n6. ANTI-HISTAMÍNICO:\n• Loratadina 10mg VO 1x/dia (prurido)\n• Hidroxizina 25mg VO 8/8h (sedativo, noite)\n\n7. EVITAR (causas conhecidas):\n• Não reintroduzir o medicamento responsável\n• Atenção à reação cruzada (beta-lactâmicos: alergia a penicilina pode ter reação cruzada com cefalosporinas, especialmente de 1ª-2ª gerações)\n\n8. SE FORMA RECORRENTE:\n• Investigar mutação IL-36RN\n• Considerar antagonistas de IL-1 (anakinra) — refratário\n• Pesquisa genética" },
      { id: "followup", title: "Acompanhamento", content: "Hospitalar (forma extensa):\n• Reavaliação diária\n• Resolução das pústulas em 3–7 dias\n• Descamação em 7–14 dias\n\nAlta:\n• Pústulas em resolução\n• Sem febre\n• Hidratação adequada\n\nAmbulatorial:\n• Retorno em 2 semanas\n• Pele recuperada em 14–21 dias\n• Sem sequelas dermatológicas\n\nORIENTAR PACIENTE:\n• Lista de medicamentos a EVITAR\n• Atenção a reação cruzada (especialmente beta-lactâmicos)\n• Cartão de alergia\n• Comunicação ao prescritores\n\nPROGNÓSTICO:\n• Excelente em jovem saudável\n• Mortalidade < 5% (principalmente em idoso com comorbidades, complicações sistêmicas)\n• Sem cicatrização ou sequela permanente em maioria" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "Prednisona (não rotineiro):\n• 0,5–1 mg/kg/dia VO\n• 5–10 dias\n• Reduzir após resolução\n• Considerar em forma extensa, eritrodermia, comprometimento sistêmico\n\nCorticoide tópico:\n• Clobetasol propionato 0,05% creme 2x/dia em áreas mais inflamadas\n• Aplicar por 5–7 dias\n\nNão se beneficia de antibiótico (não é infecção)." },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: PEGA / AGEP EXTENSA\n\n1. SUSPENDER MEDICAMENTO SUSPEITO IMEDIATAMENTE\n2. INTERNAÇÃO se extensa/febre/comorbidades\n3. SF 0,9% 100–150mL/h IV se febre alta + perdas\n4. CUIDADOS DE PELE:\n   • Compressas frias úmidas em áreas pustulosas\n   • Vaselina líquida após banho\n   • Clobetasol propionato 0,05% creme 2x/dia em áreas mais inflamadas (5–7 dias)\n5. PRURIDO/ANTIPIRÉTICO:\n   • Loratadina 10mg VO 1x/dia\n   • Paracetamol 1g VO 6/6h (sem AINE)\n   • Dipirona 1g IV 6/6h\n6. PREDNISONA (forma extensa/eritrodermia):\n   • 0,5–1 mg/kg/dia VO por 5–10 dias\n7. EXAMES:\n   • Hemograma com diferencial\n   • PCR, função renal, hepática, eletrólitos (incluir cálcio)\n   • Cultura cutânea de pústula (descartar infecção)\n   • Hemoculturas se febre\n   • Biópsia de pele (confirmar diagnóstico — pústula subcorneal espongiforme)\n8. NÃO USAR:\n   • Antibiótico empírico (pústulas são estéreis)\n   • AINE\n9. NOTIFICAÇÃO ANVISA VIGIMED\n10. CARTÃO DE ALERGIA + lista de drogas a evitar\n11. Educar paciente sobre reações cruzadas (beta-lactâmicos)\n\n⚠️ Boa resolução espontânea (1–2 semanas) — corticoide não é obrigatório\n⚠️ Cultura cutânea ESTÉRIL — não dar ATB empírico\n⚠️ PEGA recorrente → investigar mutação IL-36RN" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Sidoroff A et al. Acute Generalized Exanthematous Pustulosis (AGEP) — Validation Study of the EuroSCAR Criteria. J Cutan Pathol 2010.\n2. Speeckaert MM et al. AGEP — Clinical, Pathologic, and Genetic Insights. JEADV 2010.\n3. Feldmeyer L et al. AGEP — Pathogenesis, Genetic Background, Clinical Variants. J Invest Dermatol 2016.\n4. SBD. Consenso Brasileiro de Farmacodermia. An Bras Dermatol 2022." }
    ]
  },
  {
    id: "fp-derm5-eczema-herpetico",
    title: "Eczema Herpético (Erupção Varioliforme de Kaposi)",
    categoryId: "dermatology", category: "Dermatologia",
    tags: ["eczema herpetico", "kaposi", "HSV", "aciclovir", "atopia", "imunocomprometido"],
    sections: [
      { id: "intro", title: "Introdução", content: "Eczema herpético (erupção varioliforme de Kaposi) é infecção disseminada cutânea por HSV-1 (raramente HSV-2 ou outros vírus) em paciente com dermatose preexistente — mais comumente dermatite atópica. É emergência dermatológica com risco de queratite, encefalite e sepse bacteriana secundária. Mortalidade chega a 6% sem tratamento adequado. Início precoce de aciclovir IV é fundamental.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026." },
      { id: "def", title: "Definição", content: "Erupção cutânea disseminada por HSV-1 (ou HSV-2) em paciente com pele com barreira comprometida (dermatite, queimadura, pênfigo, micose fungoide).\n\nClassicamente:\n• Vesículas pequenas e uniformes\n• 'Punched-out' (perfuradas, em saca-bocado)\n• Em paciente com dermatite atópica em atividade\n• Disseminação rápida (24–48h)\n\nVariantes pelo vírus:\n• Eczema herpético clássico: HSV-1\n• Eczema coxsackium: enterovírus\n• Eczema vacinatum: pós-vacinação varíola (histórico — não mais)\n• Outros: VZV, HSV-2\n\nFatores de risco:\n• Dermatite atópica moderada-grave\n• AIDS, imunossupressão\n• Quimioterapia\n• Uso de corticoide tópico ou sistêmico em alta dose\n• Outras dermatoses: pênfigo, queimadura, micose fungoide, ictiose\n• Episódios prévios (recorrência possível)" },
      { id: "screening", title: "Rastreamento e Identificação", content: "SUSPEITAR em:\n• Paciente com dermatite atópica que apresenta:\n  — Piora súbita do eczema (\"agudização inusual\")\n  — Vesículas/pústulas em áreas afetadas e ao redor\n  — Febre\n  — Linfadenopatia regional\n  — Dor (eczema atópico não dói — dor é alerta)\n\n• Erupção vesicular generalizada em paciente imunocomprometido com dermatose\n\nDIFERENÇA-CHAVE COM EXACERBAÇÃO DE ECZEMA SIMPLES:\n• Eczema simples: prurido + eritema + escamas, SEM vesículas, SEM febre, SEM dor\n• Eczema herpético: VESÍCULAS, febre, dor, linfadenopatia, piora súbita\n\nALERTA — não há tempo a perder:\n• Pode evoluir para encefalite, queratite, sepse em 24–48h\n• Aciclovir IV em qualquer suspeita razoável" },
      { id: "etiology", title: "Etiologia", content: "Vírus:\n• HSV-1 (90%) — mais comum\n• HSV-2 (10%) — adultos com herpes genital\n• Variantes: coxsackium (mãos-pés-boca), VZV (raro)\n\nDermatoses subjacentes:\n• Dermatite atópica (90% — mais comum)\n• Pênfigo vulgar\n• Queimaduras\n• Doença de Darier\n• Micose fungoide / Síndrome de Sézary\n• Ictiose\n• Eczema seborreico grave\n• Eczema atópico em criança pequena\n\nMECANISMO:\n• Barreira cutânea comprometida (Th2 dominante na DA, redução de peptídeos antimicrobianos)\n• Disseminação local rápida\n• Infecção secundária bacteriana (S. aureus — frequente)\n• Risco de viremia → encefalite, hepatite\n\nFATORES PRECIPITANTES:\n• Reativação herpética (lábios, genital)\n• Imunossupressão (corticoide tópico/sistêmico)\n• Stress\n• Trauma\n• Inibidores tópicos de calcineurina (raro)" },
      { id: "clinical", title: "Apresentação Clínica", content: "Pródromo (12–24h):\n• Febre súbita (38–40°C)\n• Mal-estar\n• Adenopatia regional dolorosa\n• Piora do eczema pré-existente\n\nFase vesiculosa:\n• Vesículas/pústulas pequenas (2–3 mm), umbilicadas, uniformes\n• 'Punched-out': aparência de saca-bocado\n• Distribuição em áreas com dermatose\n• Disseminação rápida em 24–48h\n• Confluência → erosões\n• Crostas hemorrágicas em fase posterior\n• PRURIDO + DOR\n\nDistribuição:\n• Face (especialmente em criança)\n• Pescoço\n• Tronco superior\n• Onde havia dermatite\n• Pode ser localizado ou amplamente disseminado\n\nMucosas:\n• Boca, olhos, genital podem ser acometidos\n\nCOMPLICAÇÕES:\n• Queratite herpética (com cegueira potencial) — emergência oftalmológica\n• Encefalite herpética (raramente)\n• Hepatite\n• Pneumonite\n• Sepse bacteriana secundária (S. aureus, MRSA)\n• Cicatrizes (raras)\n\nMORTALIDADE:\n• < 6% com tratamento adequado\n• > 50% sem aciclovir (era pré-antiviral)" },
      { id: "diagnosis", title: "Diagnóstico", content: "Diagnóstico CLÍNICO + confirmação laboratorial:\n\nClínico:\n• Vesículas punched-out + paciente com dermatose + febre + dor\n\nConfirmação rápida (resultado em horas):\n• PCR para HSV em vesícula (padrão-ouro, alta sensibilidade)\n• Citologia de Tzanck: células gigantes multinucleadas (rápido, baixa sensibilidade)\n• Imunofluorescência direta para HSV (rápido)\n\nConfirmação posterior:\n• Cultura viral (positiva em 5–7 dias)\n• Sorologia IgM/IgG (menos útil agudamente)\n\nINVESTIGAÇÃO DE COMPLICAÇÕES:\n• Fundoscopia (queratite — encaminhar oftalmo)\n• TC/RM crânio + LCR se sinais neurológicos (encefalite)\n• Função hepática (hepatite)\n• Rx tórax se sintomas respiratórios\n• Hemograma, PCR\n• Hemoculturas (suspeita de sepse bacteriana secundária)\n• Cultura bacteriana de pele (impetiginização)\n\nLABORATÓRIO:\n• Leucocitose leve (variável)\n• PCR moderadamente elevado\n• Linfopenia (em alguns casos)" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "• Exacerbação de eczema atópico simples (sem vesículas, sem febre, sem dor)\n• Impetigo bolhoso (S. aureus — crostas melicéricas, lesões maiores)\n• Varicela (vesículas em estágios diferentes — eczema herpético tem vesículas uniformes)\n• Coxsackievírus (mãos-pés-boca, lesões em mãos, pés, boca)\n• Herpes zoster (dermátomo, dor)\n• Dermatose IgA linear (raro, idoso, bolha em colar)\n• Variola (extinta)\n• Dermatite herpetiforme (crônica, em cotovelos, joelhos)" },
      { id: "conduct", title: "Conduta", content: "TRATAMENTO IMEDIATO — NÃO ESPERAR CONFIRMAÇÃO LABORATORIAL!\n\n1. ACICLOVIR (1ª linha — iniciar AGORA):\n\nForma grave / disseminada / imunocomprometido / acometimento mucoso / sistêmico:\n• Aciclovir IV 10 mg/kg 8/8h por 7–14 dias\n• Criança: 20 mg/kg 8/8h (até 80 mg/kg/dia)\n• Ajustar para função renal (importante — nefrotóxico)\n• Hidratação (prevenir cristalúria do aciclovir)\n\nForma leve, paciente íntegro com dermatose pequena:\n• Aciclovir oral 800mg VO 5×/dia por 7–10 dias (criança 20 mg/kg/dose 5×/dia)\n• OU Valaciclovir 1g VO 8/8h\n• OU Famciclovir 500mg VO 8/8h\n\n2. INTERNAÇÃO:\n• Forma extensa\n• Acometimento facial (risco de queratite)\n• Imunocomprometido\n• Acometimento sistêmico\n• Febre alta\n• Recém-nascido (encefalite catastrófica possível)\n• Falha de via oral\n\n3. AVALIAÇÃO OFTALMOLÓGICA URGENTE:\n• Acometimento facial → avaliação oftalmo OBRIGATÓRIA\n• Queratite herpética: ataque de cegueira potencial\n• Tratamento tópico oftálmico (aciclovir colírio) + sistêmico\n\n4. ANTIBIÓTICO ANTI-STAFILOCÓCICO (impetiginização frequente):\n• Cefalexina 500mg VO 6/6h (criança 50 mg/kg/dia ÷ 6/6h)\n• OU Clindamicina 300mg VO 6/6h (se MRSA suspeito)\n• Iniciar empiricamente se eritema/exsudato sugestivos\n• Cultura de pele guia ajuste\n\n5. CONTROLE DA DERMATOSE SUBJACENTE:\n• Manter corticoide tópico de baixa-média potência (NÃO suspender — controla inflamação)\n• Hidratante (emolientes)\n• EVITAR tacrolimus tópico em fase aguda (pode piorar)\n• Tratamento sistêmico para DA grave (após resolução do herpes): considerar dupilumabe\n\n6. CUIDADOS DE SUPORTE:\n• Hidratação IV (especialmente se aciclovir IV — diluir bem)\n• Analgesia (paracetamol, dipirona; opióide se dor intensa)\n• Antipirético\n• Higiene de pele suave\n• Curativos não aderentes\n\n7. ISOLAMENTO DE CONTATO:\n• Vesículas com HSV ativo → isolamento (gotículas/contato)\n• Especialmente em hospital com recém-nascidos\n• Lavagem das mãos rigorosa\n\n8. ACOMPANHAMENTO:\n• Pediatra/clínico + dermatologia + oftalmologia (se face)\n• Avaliar comorbidades (HIV, imunossupressão se atípico)\n\n9. PROFILAXIA SECUNDÁRIA (forma recorrente):\n• Aciclovir 400mg VO 12/12h por 6–12 meses\n• Valaciclovir 500mg VO 1x/dia (alternativa)\n• Reavaliar após período" },
      { id: "followup", title: "Acompanhamento", content: "Hospitalar:\n• Reavaliação diária\n• Melhora em 2–4 dias com aciclovir\n• Vesículas viram crostas e curam em 7–14 dias\n• Sem cicatriz na maioria (pode haver hiperpigmentação)\n\nAlta:\n• Sem novas vesículas por 48h\n• Completar 7–10 dias de aciclovir VO\n• Manter ATB se infecção bacteriana\n• Plano de manejo da dermatose subjacente\n• Retorno em 1–2 semanas\n\nLONGO PRAZO:\n• Manejo otimizado da dermatite atópica (reduz risco de recorrência)\n• Considerar profilaxia antiviral em casos recorrentes\n• Educar sobre sinais de alerta (vesículas, dor, febre)\n• Vacinação contra varicela (se ainda não imune)\n\nRECIDIVA:\n• 10–25% têm episódio recorrente\n• Geralmente menos grave\n• Reiniciar tratamento precoce" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "Aciclovir IV:\n• 10 mg/kg IV em 60 min, 8/8h\n• Criança: 20 mg/kg IV 8/8h\n• HIDRATAR antes (prevenir cristalúria — risco de IRA)\n• Ajustar dose se ClCr < 50: ver tabela\n• 7–14 dias (forma disseminada)\n\nValaciclovir VO (forma leve):\n• 1g VO 8/8h por 7–10 dias\n• Pró-droga com melhor biodisponibilidade\n• Mais cara que aciclovir oral\n\nResistência ao aciclovir (raro, em imunocomprometido crônico):\n• Foscarnet 40 mg/kg IV 8/8h\n• Cidofovir (alternativa)" },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: ECZEMA HERPÉTICO\n\nFORMA EXTENSA / FACIAL / IMUNOCOMPROMETIDO:\n1. INTERNAÇÃO\n2. Hidratação: SF 0,9% 100–150mL/h IV (criança ajustar)\n3. Aciclovir 10 mg/kg IV em 60 min, 8/8h por 7–14 dias\n   • Criança: 20 mg/kg IV 8/8h\n   • Ajustar para função renal\n4. Antibiótico (impetiginização frequente):\n   • Cefalexina 500mg VO 6/6h (criança 50 mg/kg/dia ÷ 6/6h)\n   • OU Clindamicina 300mg VO 6/6h se MRSA suspeito\n5. CUIDADOS DE PELE:\n   • Banho com SF morno\n   • Vaselina liberalmente\n   • Curativos não aderentes\n   • Manter corticoide tópico em áreas inflamadas (não no eczema herpético ativo)\n6. ANALGESIA:\n   • Paracetamol 750mg VO 6/6h\n   • Dipirona 1g IV 6/6h\n7. AVALIAÇÃO OFTALMOLÓGICA URGENTE (se face)\n8. ISOLAMENTO DE CONTATO\n9. EXAMES:\n   • PCR HSV em vesícula\n   • Imunofluorescência direta\n   • Cultura viral\n   • Hemograma, PCR, função renal e hepática, eletrólitos\n   • Cultura bacteriana de pele\n   • Hemoculturas se febre alta\n10. AVALIAÇÃO DA IMUNIDADE (se imunocomprometimento suspeito):\n    • HIV\n    • Imunoglobulinas\n    • Subpopulações linfocitárias\n\nFORMA LEVE (ambulatorial — paciente íntegro, lesão pequena):\n• Valaciclovir 1g VO 8/8h por 7–10 dias\n• Cefalexina 500mg VO 6/6h\n• Retorno em 48h e 7 dias\n• Sinais de alerta: febre, piora, vesículas em olhos\n\n⚠️ Iniciar ACICLOVIR IMEDIATAMENTE em qualquer suspeita razoável — não aguardar confirmação\n⚠️ Acometimento facial = avaliação OFTALMOLÓGICA URGENTE (queratite com cegueira)\n⚠️ Hidratar antes do aciclovir IV (cristalúria → IRA)" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Wollenberg A et al. Eczema Herpeticum — Pathogenesis, Diagnosis, and Management. J Am Acad Dermatol 2017.\n2. Aronson PL et al. Risk Factors for Eczema Herpeticum. JAMA Pediatr 2014.\n3. Glesby MJ et al. Clinical Spectrum of Herpes Simplex Virus Infections in Patients with Atopic Dermatitis. Arch Dermatol 1989.\n4. SBD/SBP. Consenso Brasileiro de Eczema Herpético. Rev Bras Dermatol 2022." }
    ]
  },
  {
    id: "fp-derm5-vasculite-cutanea",
    title: "Vasculite Cutânea (Vasculite de Pequenos Vasos)",
    categoryId: "dermatology", category: "Dermatologia",
    tags: ["vasculite", "purpura palpável", "leucocitoclástica", "biopsia", "autoimune"],
    sections: [
      { id: "intro", title: "Introdução", content: "Vasculite cutânea de pequenos vasos é inflamação das paredes vasculares dérmicas, manifestando-se classicamente como púrpura palpável em membros inferiores. Pode ser limitada à pele (vasculite cutânea isolada) ou parte de doença sistêmica (vasculites ANCA, vasculite por IgA, doenças do tecido conjuntivo). A avaliação deve sempre investigar envolvimento sistêmico — especialmente renal — pois condiciona o prognóstico.\n\n⚕️ Uso exclusivo por profissional de saúde habilitado. Última revisão: Mai/2026 · ACR/EULAR 2022." },
      { id: "def", title: "Definição", content: "Vasculite: inflamação da parede de vasos sanguíneos, levando a dano tecidual por isquemia ou hemorragia.\n\nClassificação (Chapel Hill 2012, revisada):\n\nPequenos vasos:\n• Vasculite leucocitoclástica cutânea isolada\n• Vasculite por IgA (antiga púrpura de Henoch-Schönlein)\n• Vasculite crioglobulinêmica\n• Vasculite urticariforme hipocomplementêmica\n• Vasculites associadas a ANCA:\n  — Poliangeíte microscópica (MPA)\n  — Granulomatose com poliangeíte (GPA / antiga Wegener)\n  — Granulomatose eosinofílica com poliangeíte (EGPA / antiga Churg-Strauss)\n\nMédios vasos:\n• Poliarterite nodosa (PAN)\n• Doença de Kawasaki\n\nGrandes vasos:\n• Arterite temporal\n• Arterite de Takayasu\n\nCom acometimento cutâneo predominante:\n• Vasculite leucocitoclástica idiopática\n• Vasculite por IgA\n• Vasculite urticariforme\n• Vasculite crioglobulinêmica" },
      { id: "screening", title: "Rastreamento e Identificação", content: "PÚRPURA PALPÁVEL é o sinal-chave:\n• Lesões avermelhadas/violáceas que NÃO branqueiam à digitopressão\n• Elevadas (palpáveis — diferente de eritema simples)\n• Distribuição preferencial em membros inferiores (gravidade)\n\nAVALIAR ENVOLVIMENTO SISTÊMICO (essencial — define gravidade):\n• Rim: hematúria, proteinúria, IRA (glomerulonefrite — emergência)\n• Pulmão: hemoptise, dispneia (hemorragia alveolar)\n• Articulações: artralgia, artrite\n• GI: dor abdominal, hematoquezia (vasculite intestinal)\n• Sistema nervoso periférico: mononeurite múltipla\n• Sistema nervoso central: convulsão, AVC\n• Constitucional: febre, perda de peso, fadiga\n\nPERGUNTAS DE TRIAGEM:\n• 'Tem urina escura ou rosada?' (hematúria)\n• 'Tem dor abdominal?'\n• 'Tem dor articular?'\n• 'Está tossindo sangue?'\n• 'Perdeu peso recentemente sem dieta?'\n\nALERTA: vasculite cutânea + IRA = emergência → biópsia renal + corticoide IV imediato" },
      { id: "etiology", title: "Etiologia", content: "Idiopática (40–50%)\n\nInfecções (15–20%):\n• Vírus: hepatite C (crioglobulinas), HIV, hepatite B, HSV, EBV\n• Bactérias: estreptococo, S. aureus, endocardite\n• Pós-estreptocócica (clássica)\n\nDrogas (10–20%):\n• Antibióticos: penicilinas, cefalosporinas, sulfonamidas, quinolonas\n• Diuréticos: tiazídicos\n• AINE\n• Hidralazina, propiltiouracil (cANCA — vasculite ANCA induzida por droga)\n• Cocaína (cANCA, especialmente com levamisol — contaminante)\n• Alopurinol\n• Anticonvulsivantes\n\nDoenças autoimunes (10–15%):\n• Lúpus eritematoso sistêmico\n• Artrite reumatoide\n• Síndrome de Sjögren\n\nNeoplasias (5%):\n• Linfoma, leucemia (especialmente leucemia mieloide crônica)\n• Tumores sólidos (raros)\n\nVasculites primárias (15%):\n• ANCA-associadas (GPA, MPA, EGPA)\n• Vasculite por IgA\n• Crioglobulinêmica\n\nPÚRPURA DE HENOCH-SCHÖNLEIN (vasculite por IgA):\n• Mais comum em criança (4–11 anos)\n• Tetrade: púrpura palpável + artralgia + dor abdominal + acometimento renal\n• Pós-infecção respiratória alta (estreptococo)" },
      { id: "clinical", title: "Apresentação Clínica", content: "MANIFESTAÇÕES CUTÂNEAS:\n• Púrpura palpável (mais característica)\n• Petéquias\n• Vesículas hemorrágicas\n• Nódulos eritematosos (vasculite de médio vaso)\n• Úlceras (necrose)\n• Livedo reticular ('rede' violácea)\n• Necrose / gangrena (vasculite grave)\n\nDistribuição:\n• Membros inferiores (mais comum — gravidade)\n• Pode subir para tronco em vasculites graves\n• Áreas de pressão\n• Sinal de Köbner em áreas traumatizadas\n\nMANIFESTAÇÕES SISTÊMICAS (avaliar SEMPRE):\n\nRENAL (mais grave):\n• Hematúria microscópica/macroscópica\n• Proteinúria (variável a nefrótica)\n• HAS\n• IRA progressiva\n• GNRP (Glomerulonefrite Rapidamente Progressiva — emergência)\n\nPULMÃO:\n• Hemoptise\n• Dispneia\n• Hemorragia alveolar difusa (DAH) — mortalidade alta\n• Nódulos pulmonares (GPA)\n• Granulomas (GPA)\n\nGI:\n• Dor abdominal cólica (intestinal — Henoch-Schönlein)\n• Hematoquezia, melena\n• Intussuscepção (criança)\n• Pancreatite\n\nNEUROLÓGICO:\n• Mononeurite múltipla\n• Polineuropatia\n• AVC\n• Convulsão\n\nORL (especialmente GPA):\n• Sinusite crônica\n• Otite média\n• Selador nasal (perfuração septal — sinal-chave)\n• Estridor (estenose subglótica)\n\nARTICULAR:\n• Artralgia\n• Artrite (não-erosiva)\n\nCONSTITUCIONAL:\n• Febre\n• Perda de peso\n• Fadiga" },
      { id: "diagnosis", title: "Diagnóstico", content: "1. CLÍNICO:\n• Púrpura palpável + outros sinais\n\n2. BIÓPSIA DE PELE (essencial):\n• Lesão recente (< 48h)\n• Múltiplos sítios\n• Histopatologia: vasculite leucocitoclástica\n  — Infiltrado neutrofílico perivascular\n  — Necrose fibrinoide\n  — Leucocitoclasia (núcleos fragmentados)\n  — Hemorragia\n• IMUNOFLUORESCÊNCIA DIRETA:\n  — IgA = vasculite por IgA\n  — IgG, C3 = imunocomplexos (crioglobulinas, LES)\n  — Pauci-imune = ANCA-associada\n\n3. SCREENING DE ENVOLVIMENTO SISTÊMICO (TODOS):\n• EAS + sedimento urinário (proteinúria, hematúria, cilindros)\n• Creatinina sérica, ureia\n• Hemograma com diferencial\n• PCR, VHS\n• Proteinúria de 24h ou relação proteína/creatinina\n• ECG (cardiopatia, vasculite cardíaca)\n• Rx tórax (nódulos, infiltrados)\n\n4. INVESTIGAÇÃO IMUNOLÓGICA (busca da causa):\n• ANCA (PR3-cANCA e MPO-pANCA): vasculites ANCA\n• ANA, anti-dsDNA, anti-Sm: LES\n• Fator reumatoide, anti-CCP: AR\n• C3, C4: hipocomplementemia em LES, urticariforme\n• Crioglobulinas (na geladeira durante 1 semana)\n• Imunoglobulinas (IgA elevada em Henoch-Schönlein)\n• HIV, hepatite B, C\n• ASO (estreptococo)\n• Hemocultura (endocardite)\n\n5. SE ENVOLVIMENTO PULMONAR:\n• TC tórax\n• Broncoscopia + LBA (hemorragia alveolar)\n\n6. SE ENVOLVIMENTO RENAL:\n• Biópsia renal urgente (define tratamento e prognóstico)\n• Imunofluorescência renal" },
      { id: "differential", title: "Diagnóstico Diferencial", content: "Púrpura NÃO palpável (não vasculite):\n• Trombocitopenia (plaquetas baixas)\n• Distúrbios de coagulação\n• Senil (idoso, sem inflamação)\n• Por trauma\n\nPúrpura palpável de outras causas:\n• Endocardite infecciosa (sopro, vegetações)\n• Sepse (CIVD)\n• Embolismo séptico\n• Coagulopatia consumptiva\n\nLesões similares:\n• Eritema multiforme (alvos, mucosa)\n• Vasculite séptica (Gonococcemia, meningococcemia — investigar hemoculturas)\n• Síndrome de Sweet (placas eritematosas dolorosas — pode coexistir)" },
      { id: "conduct", title: "Conduta", content: "1. AVALIAR ENVOLVIMENTO SISTÊMICO IMEDIATAMENTE:\n• Função renal, EAS, sedimento\n• Rx tórax\n• Avaliação completa de órgãos\n\n2. SUSPENDER DROGA SUSPEITA (se identificada)\n\n3. TRATAR INFECÇÃO ASSOCIADA (se presente):\n• Endocardite, hepatite C, estreptococo\n\nFORMAS LIMITADAS À PELE (sem envolvimento sistêmico):\n• Observação\n• Repouso, elevação de membros\n• AINE (paracetamol se contraindicação)\n• Anti-histamínico se prurido\n• Corticoide tópico potente (clobetasol) em áreas inflamadas\n• Prednisona oral baixa dose (10–20mg/dia) se sintomático\n• Pode resolver espontaneamente em 2–4 semanas\n\nFORMAS COM ENVOLVIMENTO SISTÊMICO:\n\nNEFRITE OU HEMORRAGIA ALVEOLAR (emergência — vasculite grave):\n• Pulsoterapia com Metilprednisolona 500–1000mg IV/dia × 3 dias\n• Depois prednisona 1 mg/kg/dia VO\n• + Ciclofosfamida (IV ou oral) OU Rituximabe\n• Plasmaférese em casos graves (hemorragia alveolar, IRA dialítica)\n• Internação UTI se necessário\n• Suporte específico (diálise, ventilação)\n\nVASCULITE POR IGA (Henoch-Schönlein):\n• Criança: maioria autolimitada (apenas suporte)\n• Adultos: maior risco renal — prednisona 1 mg/kg/dia se acometimento renal/abdominal\n• Reavaliação renal frequente\n\nVASCULITES ANCA (GPA, MPA, EGPA):\n• Indução: pulso de corticoide + ciclofosfamida OU rituximabe\n• Manutenção: azatioprina ou metotrexato OU rituximabe periódico\n• Plasmaférese se IRA dialítica ou hemorragia alveolar\n• Especialista (reumatologia, nefrologia)\n\nCRIOGLOBULINEMIA TYPE II (hepatite C):\n• Tratar hepatite C (DAA — antivirais diretos)\n• Rituximabe se vasculite grave\n• Plasmaférese em fulminante\n\nNÃO USAR rotineiramente:\n• Antibiótico (só se infecção)\n• Anticoagulação (não previne)\n\nMANEJO MULTIDISCIPLINAR:\n• Dermatologia + reumatologia + nefrologia + pneumologia conforme acometimento" },
      { id: "followup", title: "Acompanhamento", content: "Vasculite limitada à pele:\n• Resolução em 2–4 semanas (maioria)\n• Recorrência possível\n• Seguimento por 6–12 meses (excluir doença sistêmica de evolução lenta)\n\nVasculite sistêmica:\n• Acompanhamento multidisciplinar prolongado\n• Indução por 3–6 meses, manutenção por 1–2 anos\n• Monitorar: ANCA, creatinina, hemograma, função pulmonar\n• Recidiva é comum (especialmente GPA)\n\nMONITORIZAÇÃO DE TRATAMENTO IMUNOSSUPRESSOR:\n• Hemograma\n• Função renal e hepática\n• Infecção (Pneumocystis profilaxia: SMX-TMP 3x/semana)\n• Osteoporose\n• Glicemia\n• Pressão arterial\n\nGESTANTE:\n• Vasculite por IgA pode ocorrer\n• Discutir com obstetra de alto risco" },
      { id: "treatment", title: "Abordagem Terapêutica", content: "Prednisona:\n• 1 mg/kg/dia VO (vasculite com acometimento sistêmico moderado)\n• Reduzir 10% a cada 2 semanas conforme resposta\n\nPulsoterapia Metilprednisolona:\n• 500–1000mg IV/dia × 3 dias (formas graves)\n• Indicações: GNRP, hemorragia alveolar, vasculite grave\n\nCiclofosfamida:\n• Indução: 750 mg/m² IV mensal × 6 OU 2 mg/kg/dia VO\n• Especialista monitorar (mielotoxicidade, infecção, cistite hemorrágica)\n\nRituximabe (vasculite ANCA):\n• 375 mg/m² IV semanal × 4 (indução)\n• 1g IV no dia 0 + 14 (esquema RA)\n• Alternativa segura à ciclofosfamida" },
      { id: "prescriptions", title: "Guia de Prescrições", content: "PRESCRIÇÃO: VASCULITE CUTÂNEA — AVALIAÇÃO\n\n1. EXAMES INICIAIS (TODOS):\n   • Hemograma + plaquetas\n   • PCR, VHS\n   • Função renal (creatinina, ureia)\n   • EAS + sedimento urinário (hematúria, proteinúria, cilindros)\n   • Proteinúria 24h (se EAS alterado)\n   • Função hepática\n   • Rx tórax\n   • ECG\n\n2. INVESTIGAÇÃO IMUNOLÓGICA:\n   • ANCA (PR3, MPO)\n   • ANA, anti-dsDNA\n   • FR, anti-CCP\n   • C3, C4\n   • Crioglobulinas\n   • Imunoglobulinas (IgA)\n   • Sorologias: HIV, HBV, HCV\n   • Hemoculturas (se febre)\n   • ASO\n\n3. BIÓPSIA DE PELE (lesão recente — < 48h):\n   • Para histopatologia + imunofluorescência direta\n\n4. SE ACOMETIMENTO RENAL/SISTÊMICO:\n   • Internação\n   • Biópsia renal urgente\n   • Acionar nefrologia + reumatologia\n   • Considerar pulsoterapia Metilprednisolona 1g IV/dia × 3 dias\n   • Após pulso: Prednisona 1mg/kg/dia VO\n   • Discutir ciclofosfamida ou rituximabe\n   • Plasmaférese se hemorragia alveolar/GNRP\n\n5. FORMAS APENAS CUTÂNEAS:\n   • Repouso, elevação dos membros\n   • Meia compressiva\n   • Paracetamol 750mg VO 6/6h (analgesia)\n   • Loratadina 10mg VO 1x/dia (anti-histamínico)\n   • Clobetasol propionato 0,05% creme 2x/dia em áreas mais inflamadas\n   • Considerar prednisona 0,5 mg/kg/dia se persistente/sintomático\n   • Acompanhamento dermatológico 2 semanas\n\n6. IDENTIFICAR E TRATAR CAUSA:\n   • Suspender droga suspeita\n   • Tratar infecção (HCV → DAA; estreptococo → ATB)\n   • Tratar neoplasia subjacente\n\n7. PROFILAXIAS SE IMUNOSSUPRESSOR:\n   • SMX-TMP 960mg VO 3x/semana (Pneumocystis)\n   • Cálcio + vitamina D + bifosfonato (osteoporose)\n   • Omeprazol\n\n⚠️ Toda vasculite cutânea precisa de avaliação de envolvimento SISTÊMICO\n⚠️ Vasculite cutânea + IRA = emergência (GNRP) — corticoide IV imediato\n⚠️ Vasculite por IgA em adulto: maior risco renal — vigilância" },
      { id: "references", title: "Referências Bibliográficas", content: "1. Sunderkötter CH et al. Cutaneous Vasculitis — 2018 International Chapel Hill Consensus Conference Update. Arthritis Rheumatol 2018.\n2. Yates M et al. EULAR/ERA-EDTA Recommendations for ANCA-Associated Vasculitis 2022.\n3. Ozen S et al. EULAR/PReS Endorsed Consensus Criteria for the Classification of Childhood Vasculitides. Ann Rheum Dis 2010.\n4. SBR/SBN. Consenso Brasileiro de Vasculites. Rev Bras Reumatol 2022." }
    ]
  }
];
